COLLDATA("seeratency","ur",[[1900,"[تصویر: نقشہ: مدینہ منورہ (یثرب) — مسجد قباء اور وادی رانوناء]\nمدینہ منورہ (یثرب)، مسجد رسول اللہ صلی اللہ علیہ وسلم، البقیع، بنو نجار، بنو حارث بن خزرج، حرۃ واقم (اللابة الشرقية)، جبل سلع، وادی بطحان، بنو زریق، بنو ساعدہ، بنو قینقاع، وادی مہزور، بنو قریظہ، وادی مذینب، قلعہ کعب بن اشرف، بنو نضیر، العالیہ، بنو واقف، بنو بیاضہ، بنو سالم بن عوف، وادی رانوناء، مسجد جمعہ، بنو عوف بن خزرج، بنو عوف بن مالک بن اوس، مسجد قباء، قباء، بنو انیف، جبل عیر، بدائع\n§مسجد قباء اور وادی رانوناء\n﴿لَا تَقُمْ فِيهِ أَبَدًا ۚ لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا ۚ وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ﴾ ’’نہ کھڑے ہوں آپ اس مسجد (ضرار) میں کبھی بھی، البتہ وہ مسجد کہ بنیاد رکھی گئی ہے (اس کی) تقویٰ پر پہلے ہی دن سے، زیادہ حق دار ہے اس کی کہ کھڑے ہوں آپ اس میں، اس میں تو ایسے لوگ ہیں جو پسند کرتے ہیں اس بات کو کہ پاک ہوں وہ اور اللہ پسند کرتا ہے پاک رہنے والوں کو‘‘ (التوبة 9:108)","",{"v":400310,"im":["v4_p310.jpg"]}],[1901,"کرنا ہم پر واجب ہے اور اس وقت تک واجب ہے جب تک پکارنے والا اللہ کو پکارتا رہے گا۔ اے ذات پاک جنھیں اللہ نے ہمارے لیے پیغمبر بنا کر بھیجا ہے! آپ ایک ایسا دین لے کر آئے ہیں جس کی اطاعت کی جائے گی۔(1)\n§مدینہ میں پہلا جمعہ\nدین اسلام میں اجتماعیت کو ایک خاص اہمیت حاصل ہے۔ ایک جگہ اکٹھے ہو کر ایک امام کے پیچھے اپنے عجز و انکسار کا اظہار اور اللہ تعالیٰ کی بندگی کا اعلان اسلام میں بہت محبوب ہے۔ اس کی ایک صورت نماز پنجگانہ ہے۔ اس سے بڑی اجتماعی عبادت جمعہ کے روز جمعۃ المبارک کی نماز ہے۔\nجمہور علماء کے قول کے مطابق جمعہ مدینہ میں فرض ہوا تھا۔ اس کی فرضیت کے دلائل میں سے ایک دلیل سورۃ الجمعہ کا نزول ہے جس میں ایمان والوں کو حکم دیا گیا:\n﴿يَاأَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَوةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ﴾\n’’اے ایمان والو! جب تمھیں جمعہ کے دن نماز کے لیے پکار لگائی جائے تو اللہ کے ذکر (یاد) کی طرف جلدی آؤ۔‘‘(2)\nاب مسلمان دارالکفر سے ہجرت کر کے دارالامن مدینہ طیبہ پہنچ چکے تھے۔ رسول کریم صلی اللہ علیہ وسلم نے اپنا پہلا پڑاؤ قباء بستی میں کیا۔ یہاں آپ صلی اللہ علیہ وسلم نے پیر، منگل، بدھ اور جمعرات کو قیام کیا۔ بعض روایات میں چودہ دن قیام کا ذکر ملتا ہے۔ اس مختصر قیام کے بعد جمعۃ المبارک کے دن آپ مدینہ کی طرف عازم سفر ہوئے۔ آپ اپنی اونٹنی القصواء پر سوار تھے۔ مدینہ سے آئے ہوئے آپ کی ننھیال بنو نجار اور دیگر قبائل کے جانثار مسلح حالت میں آپ کے ساتھ تھے۔ چلتے چلتے بنو سالم بن عوف کی بستی (موجودہ رانوناء) میں زوال کا وقت شروع ہوگیا تو آپ نے وہیں صحابہ کو جمعہ پڑھایا۔ اس موقع پر آپ صلی اللہ علیہ وسلم کے ساتھ سو افراد تھے۔ ہجرت کے بعد مدینہ میں آپ صلی اللہ علیہ وسلم کا یہ پہلا جمعہ تھا۔(3)","",{"v":400311,"fn":"(1) دلائل النبوة للبيهقي: 506,507/2، بعض محققین ان اشعار کو غزوہ تبوک سے واپسی کے موقع پر شمار کرتے ہیں۔ (دیکھیے: دلائل النبوة للبيهقي: 266/5، زاد المعاد: 551/3)\n(2) (الجمعة 62:9)\n(3) الطبقات لابن سعد: 236/1، السيرة لابن هشام: 494/2، وفاء الوفا: 256/1، فتح الباري لابن حجر: 307/7"}],[1902,"نیز نبی صلی اللہ علیہ وسلم کا مکہ میں جمعہ ادا کرنا ثابت بھی نہیں۔ آپ صلی اللہ علیہ وسلم اس سے قبل ایسے پرامن ٹھکانے میں نہیں تھے کہ وہاں جمعہ کے روز وعظ کیا جاتا۔ مشرکین مکہ آپ کو تکالیف سے دوچار کرتے تھے۔(1) اسی دن سے یثرب کا نام مدینۃ الرسول رکھ دیا گیا۔ بعد میں یہ نام مختصر ہو کر المدینہ مشہور ہو گیا۔\nامام احمد بن حنبل رحمہ اللہ نے فرمایا ہے: اسلام میں پہلا جمعہ وہی ہے جو مدینہ میں سیدنا مصعب بن عمیر رضی اللہ عنہ نے پڑھایا تھا۔\nحافظ ابن رجب رحمہ اللہ لکھتے ہیں: علماء کی ایک جماعت نے کہا ہے کہ جمعہ ہجرت سے پہلے مکہ میں فرض ہو گیا تھا اور نبی صلی اللہ علیہ وسلم ہجرت سے پہلے جمعہ پڑھتے بھی تھے۔ اس کی دلیل میں انھوں نے حضرت معافی بن عمران رحمہ اللہ کی ایک حدیث پیش کی ہے جسے امام نسائی رحمہ اللہ نے کتاب الجمعہ میں سیدنا ابو ہریرہ رضی اللہ عنہ کے واسطے سے بیان کیا ہے۔ وہ فرماتے ہیں: مکہ میں رسول اللہ صلی اللہ علیہ وسلم کے جمعہ ادا کرنے کے بعد پہلا جمعہ بحرین میں عبدالقیس کی بستی جواثاء میں ادا کیا گیا۔ جبکہ صحیح بخاری کے الفاظ ہیں:\nرسول اللہ صلی اللہ علیہ وسلم کی مسجد کے بعد پہلا جمعہ بحرین میں عبدالقیس کی بستی جواثیٰ میں پڑھا گیا۔(2)\n[تصویر: ماضی کے بحرین میں مسجد جواثاء (ہجر، سعودی عرب)]\nامام وکیع رحمہ اللہ نے بھی اسی طرح کی ایک روایت بیان کی ہے۔ اس کے الفاظ ہیں: اسلام میں پہلا جمعہ جو مدینہ میں رسول اللہ صلی اللہ علیہ وسلم کی مسجد کے بعد ادا کیا گیا، وہ بحرین کی ایک بستی جواثاء میں ادا کیا گیا۔(3)\nبخاری اور ابوداود کی حدیثوں سے پتہ چلا کہ راوی حدیث معافی بن عمران رحمہ اللہ کو وہم ہوا ہے۔ ان کے مقابل اکثریت کی روایت درست ہے۔(4)\nکتب تاریخ و سیرت میں آپ صلی اللہ علیہ وسلم سے اس جمعے کا خطبہ ان الفاظ کے ساتھ منقول ہے:\n«الْحَمْدُ لِلَّهِ أَحْمَدُهُ وَأَسْتَعِينُهُ وَأَسْتَغْفِرُهُ وَأَسْتَهْدِيهِ وَأُؤْمِنُ بِهِ وَلَا أَكْفُرُهُ وَأُعَادِي مَنْ يَكْفُرُهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، أَرْسَلَهُ بِالْهُدَىٰ","",{"v":400312,"fn":"(1) فتح الباري: 326,327/7، السيرة النبوية لابن كثير، ص: 221,222\n(2) صحيح البخاري: 892\n(3) سنن أبي داود: 1068\n(4) فتح الباري لابن رجب: 326-329/5","im":["v4_p312.jpg"]}],[1903,"وَالنُّورِ وَالْمَوْعِظَةِ عَلَىٰ فَتْرَةٍ مِّنَ الرُّسُلِ وَقِلَّةٍ مِّنَ الْعِلْمِ وَضَلَالَةٍ مِّنَ النَّاسِ، وَانْقِطَاعٍ مِّنَ الزَّمَانِ، وَدُنُوٍّ مِّنَ السَّاعَةِ، وَقُرْبٍ مِّنَ الْأَجَلِ، مَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ رَشَدَ، وَمَنْ يَعْصِهِمَا فَقَدْ غَوَىٰ وَفَرَّطَ وَضَلَّ ضَلَالًا بَعِيدًا.\nأُوصِيكُمْ بِتَقْوَى اللَّهِ، فَإِنَّهُ خَيْرُ مَا أَوْصَىٰ بِهِ الْمُسْلِمُ الْمُسْلِمَ أَنْ يَحُضَّهُ عَلَى الْآخِرَةِ، وَأَنْ يَأْمُرَهُ بِتَقْوَى اللَّهِ، فَاحْذَرُوا مَا حَذَّرَكُمُ اللَّهُ مِنْ نَّفْسِهِ، وَلَا أَفْضَلَ مِنْ ذَٰلِكَ نَصِيحَةٌ، وَلَا أَفْضَلَ مِنْ ذَٰلِكَ ذِكْرًا، وَإِنَّ تَقْوَى اللَّهِ لِمَنْ عَمِلَ بِهِ عَلَىٰ وَجَلٍ، وَمَخَافَةٍ مِّنْ رَّبِّهِ، عَوْنُ صِدْقٍ عَلَىٰ مَا تَبْغُونَ مِنْ أَمْرِ الْآخِرَةِ، وَمَنْ يُصْلِحِ الَّذِي بَيْنَهُ وَبَيْنَ اللَّهِ مِنْ أَمْرِهِ فِي السِّرِّ وَالْعَلَانِيَةِ، لَا يَنْوِي بِذَٰلِكَ إِلَّا وَجْهَ اللَّهِ يَكُنْ لَّهُ ذِكْرًا فِي عَاجِلِ أَمْرِهِ، وَذُخْرًا فِي مَا بَعْدَ الْمَوْتِ، حِينَ يَفْتَقِرُ الْمَرْءُ إِلَىٰ مَا قَدَّمَ، وَمَا كَانَ مِنْ سِوَىٰ ذَٰلِكَ يَوَدُّ لَوْ أَنَّ بَيْنَهُ وَبَيْنَهُ أَمَدًا بَعِيدًا وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ وَاللَّهُ رَؤُوفٌ بِالْعِبَادِ.\nوَالَّذِي صَدَّقَ قَوْلَهُ وَأَنْجَزَ وَعْدَهُ لَا خُلْفَ لِذَٰلِكَ، فَإِنَّهُ يَقُولُ عَزَّ وَجَلَّ: ﴿مَا يُبَدَّلُ الْقَوْلُ لَدَيَّ وَمَا أَنَا بِظَلَّامٍ لِّلْعَبِيدِ﴾ فَاتَّقُوا اللَّهَ فِي عَاجِلِ أَمْرِكُمْ وَآجِلِهِ فِي السِّرِّ وَالْعَلَانِيَةِ، فَإِنَّهُ مَنْ يَتَّقِ اللَّهَ يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُعْظِمْ لَهُ أَجْرًا، وَمَنْ يَتَّقِ اللَّهَ فَقَدْ فَازَ فَوْزًا عَظِيمًا، وَإِنَّ تَقْوَى اللَّهِ يُوقِي مَقْتَهُ، وَيُوقِي عُقُوبَتَهُ، وَيُوقِي سَخَطَهُ، وَإِنَّ تَقْوَى اللَّهِ يُبَيِّضُ الْوُجُوهَ وَيُرْضِي الرَّبَّ، وَيَرْفَعُ الدَّرَجَةَ.\nخُذُوا بِحَظِّكُمْ وَلَا تُفَرِّطُوا فِي جَنْبِ اللَّهِ، قَدْ عَلَّمَكُمُ اللَّهُ كِتَابَهُ، وَنَهَجَ لَكُمْ سَبِيلَهُ، لِيَعْلَمَ الَّذِينَ صَدَقُوا وَيَعْلَمَ الْكَاذِبِينَ، فَأَحْسِنُوا كَمَا أَحْسَنَ اللَّهُ إِلَيْكُمْ، وَعَادُوا أَعْدَاءَهُ، وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ وَسَمَّاكُمُ الْمُسْلِمِينَ، لِيَهْلِكَ مَنْ هَلَكَ عَنْ بَيِّنَةٍ، وَيَحْيَىٰ مَنْ حَيَّ عَنْ بَيِّنَةٍ، وَلَا قُوَّةَ إِلَّا بِاللَّهِ، فَأَكْثِرُوا ذِكْرَ اللَّهِ وَاعْمَلُوا لِمَا بَعْدَ الْيَوْمِ، فَإِنَّهُ مَنْ يُصْلِحْ مَا بَيْنَهُ وَبَيْنَ اللَّهِ يَكْفِهِ اللَّهُ مَا بَيْنَهُ وَبَيْنَ النَّاسِ، ذَٰلِكَ بِأَنَّ اللَّهَ يَقْضِي عَلَى النَّاسِ وَلَا يَقْضُونَ عَلَيْهِ، وَيَمْلِكُ مِنَ النَّاسِ وَلَا يَمْلِكُونَ مِنْهُ، اللَّهُ","",{"v":400313}],[1904,"أَكْبَرُ، وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَظِيمِ»\n’’حمد و ستائش اللہ کے لیے ہے۔ میں اس کی حمد کرتا ہوں۔ مدد، بخشش اور ہدایت اسی سے چاہتا ہوں۔ میرا ایمان اسی پر ہے۔ میں اس کی نافرمانی نہیں کرتا اور نافرمانی کرنے والوں سے عداوت رکھتا ہوں۔ میری گواہی یہ ہے کہ اللہ کے سوا عبادت کے لائق کوئی بھی نہیں۔ وہ یکتا ہے، اس کا کوئی شریک نہیں۔ محمد صلی اللہ علیہ وسلم اس کا بندہ اور رسول ہے۔ اس نے محمد صلی اللہ علیہ وسلم کو ہدایت، نور اور نصیحت کے ساتھ ایسے زمانے میں بھیجا ہے جب کہ مدتوں سے کوئی رسول دنیا پر نہ آیا تھا، علم گھٹ گیا اور گمراہی بڑھ گئی تھی۔ اسے آخری زمانے میں قیامت کے قریب اور موت کی نزدیکی کے وقت بھیجا گیا۔ جو کوئی اللہ اور اس کے رسول کی اطاعت کرتا ہے، وہی راہ یاب ہے اور جس نے اللہ اور اس کے رسول کا حکم نہ مانا، وہ بھٹک گیا، اس نے کوتاہی کی اور سخت گمراہی میں پھنس گیا۔\n(مسلمانو!) میں تمھیں اللہ سے تقویٰ کی وصیت کرتا ہوں۔ بہترین وصیت جو مسلمان، مسلمان کو کر سکتا ہے، یہ ہے کہ اسے آخرت کے لیے آمادہ کرے اور اللہ سے تقویٰ کا حکم دے۔ لوگو! اللہ نے تمھیں جو اپنی ذات سے ڈرایا ہے، اس سے ڈرو۔ اس سے بڑھ کر کوئی نصیحت ہے نہ اس سے بڑھ کر کوئی ذکر ہے۔ یاد رکھو! اس شخص کے لیے جو اللہ سے ڈر کر کام کر رہا ہے، تقویٰ امور آخرت کے بارے میں بہترین مدد ثابت ہوگا۔ اور جب کوئی شخص اپنے اور اللہ کے درمیان کا معاملہ خفیہ و ظاہر میں درست کرے گا اور ایسا کرنے میں اس کی نیت خالص ہوگی تو ایسا کرنا اس کے لیے دنیا میں ذکر اور موت کے بعد، جب انسان کو اعمال کی ضرورت و قدر معلوم ہوگی، ذخیرہ بن جائے گا۔\nلیکن اگر کوئی ایسا نہیں کرتا تو (اس کا ذکر اس آیت میں ہے:) وہ پسند کرے گا کہ اس کے اور اس کے اعمال کے درمیان دور کا فاصلہ ہوتا۔ اللہ تم کو اپنی ذات سے ڈراتا ہے اور اللہ تو اپنے بندوں پر نہایت مہربان ہے۔’ اور جس شخص نے اللہ کے حکم کو سچ جانا اور اس کے وعدوں کو پورا کیا تو اس کی بابت یہ ارشاد الٰہی موجود ہے: ﴿مَا يُبَدَّلُ الْقَوْلُ لَدَيَّ وَمَا أَنَا بِظَلَّامٍ لِّلْعَبِيدِ﴾ (ق 50:29) ‘ہمارے ہاں بات نہیں بدلتی اور ہم اپنے بندوں پر ظلم نہیں کرتے۔‘‘\nمسلمانو! اپنے موجودہ اور آیندہ، ظاہر اور خفیہ کاموں میں اللہ سے تقویٰ کو پیش نظر رکھو! کیونکہ جو اللہ سے ڈرے تو وہ اس سے اس کی برائیاں دور کر دیتا ہے اور اسے زیادہ اجر دیتا ہے۔ تقویٰ والے وہ ہیں جو بہت","",{"v":400314}],[1905,"بڑی مراد کو پہنچ جائیں گے۔ یہ تقویٰ ہی ہے جو اللہ کی بیزاری، عذاب اور غصہ کو دور کر دیتا ہے۔ یہ تقویٰ ہی ہے جو چہرہ کو درخشاں، پروردگار کو خوشنود اور درجہ کو بلند کرتا ہے۔\nمسلمانو! اپنا نصیب لے لو مگر حقوق الٰہی میں فروگزاشت نہ کرو۔ خدا نے اسی لیے تم کو اپنی کتاب سکھائی اور اپنا رستہ دکھایا ہے تاکہ وہ راست بازوں اور کاذبوں کو ظاہر کر دے۔ لوگو! اللہ نے تمھارے ساتھ عمدہ برتاؤ کیا ہے، تم بھی لوگوں کے ساتھ ایسا ہی کرو اور جو اللہ کے دشمن ہیں، انھیں دشمن سمجھو اور اللہ کے راستے میں پوری ہمت اور توجہ سے کوشش کرو۔ اس نے تم کو برگزیدہ بنایا اور تمھارا نام مسلمان رکھا ہے تاکہ ہلاک ہونے والا بھی روشن دلائل پر ہلاک ہو اور زندگی پانے والا بھی روشن دلائل پر زندگی پائے اور سب نیکیاں اللہ کی مدد سے ہیں۔ لوگو! اللہ کا ذکر کرو اور آئندہ زندگی کے لیے عمل کرو، کیونکہ جو شخص اپنے اور اللہ کے درمیان کا معاملہ درست کر لیتا ہے، اللہ تعالیٰ اس کے اور لوگوں کے درمیان کے معاملے کو درست کر دیتا ہے۔ ہاں! اللہ بندوں پر حکم چلاتا ہے اور اس پر کسی کا حکم نہیں چلتا۔ اللہ بندوں کا مالک ہے اور بندوں کو اس پر کچھ اختیار نہیں۔ اللہ سب سے بڑا ہے اور ہم کو (نیکی کرنے کی) طاقت اسی عظمت والے سے ملتی ہے۔(1)\n§اسلام میں علی الاطلاق پہلا جمعہ\nرسول اللہ صلی اللہ علیہ وسلم کے مدینہ تشریف لانے سے پہلے مدینہ کے علاقے حرہ بنی بیاضہ کی وادی ہزم نبیت کے محلے نقیع الخضمات میں پہلا جمعہ پڑھا گیا۔ اس کی دلیل کعب بن مالک رضی اللہ عنہ کی حدیث ہے۔ وہ جب بھی جمعہ کی اذان سنتے تو اسعد بن زرارہ رضی اللہ عنہ کے لیے مغفرت کی دعا ضرور کرتے۔ ان کے بیٹے نے ان سے اس کے بارے میں دریافت کیا تو انھوں نے فرمایا:\nكَانَ أَوَّلَ مَنْ صَلَّىٰ بِنَا صَلَاةَ الْجُمُعَةِ قَبْلَ مَقْدَمِ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم مِنْ مَكَّةَ فِي نَقِيعِ الْخَضِمَاتِ فِي هَزْمِ النَّبِيتِ مِنْ حَرَّةِ بَنِي بَيَاضَةَ.\n’’وہ پہلے شخص تھے جنھوں نے ہمیں رسول اللہ صلی اللہ علیہ وسلم کی مکہ سے تشریف آوری سے پہلے حرہ بنی بیاضہ میں ہزم نبیت کے اندر نقیع الخضمات (پانی جمع ہونے کے نشیبی میدان) میں جمعہ پڑھایا تھا۔‘‘(2)","",{"v":400315,"fn":"(1) تاريخ الطبري: 115,116/2، جامع الآثار في السير ومولد المختار لابن ناصر الدين الدمشقي: 283,284/5\n(2) سنن أبي داود: 1069، سنن ابن ماجه: 1082"}],[1906,"شیخ ابو ہبہ اللہ نے لکھا ہے: نبی صلی اللہ علیہ وسلم نے قباء میں پیر، منگل، بدھ اور جمعرات کو قیام کیا، پھر جمعہ کے دن پاکیزہ شہر مدینہ طیبہ کا قصد فرمایا۔ جمعہ کی نماز کا وقت بنی سالم بن عوف کی بستی میں اس مسجد کی جگہ ہو گیا جو آج کل وادی رانوناء کے اندر ہے۔ مدینہ میں یہ پہلا جمعہ تھا جو رسول اللہ صلی اللہ علیہ وسلم نے ادا فرمایا۔ بلکہ یہ بھی کہا جاتا ہے کہ یہ مطلقاً جمعہ کی پہلی نماز تھی جو آپ صلی اللہ علیہ وسلم نے پڑھائی۔ مکہ میں مشرکین کی طرف سے شدید مخالفت اور آپ صلی اللہ علیہ وسلم اور آپ کے صحابہ کو ایذائیں دینے کی بنا پر صحابہ کا اس طور مجتمع ہونا کہ ایسا جمعہ پڑھا جائے جس میں خطبہ، اعلان توحید اور وعظ و نصیحت ہو، ممکن نہیں تھا۔\nاس جمعہ میں آپ صلی اللہ علیہ وسلم نے مسلمانوں کو انتہائی بلیغ اور پراثر خطبہ ارشاد فرمایا جس سے ایمان و یقین بڑھ جاتا ہے۔ اس خطبے میں آپ صلی اللہ علیہ وسلم نے امت کو نصیحتیں فرمائیں، نیز اچھے کاموں کی ترغیب دی اور برے کاموں سے ڈرایا۔(1)\n§سیدنا سلمان فارسی رضی اللہ عنہ کا قبول اسلام\nابھی رسول اللہ صلی اللہ علیہ وسلم قباء ہی میں قیام فرما تھے کہ سیدنا سلمان فارسی رضی اللہ عنہ اپنے ساتھ بطور صدقہ کچھ کھجوریں لائے۔ رسول اکرم صلی اللہ علیہ وسلم سے عرض کرنے لگے: آپ نیک آدمی ہیں۔ آپ کے ساتھ ضرورت مند لوگ بھی ہیں، لہٰذا یہ صدقہ قبول فرمائیں۔ آپ صلی اللہ علیہ وسلم نے وہ کھجوریں خود نہ کھائیں، اپنے ساتھیوں سے فرمایا: کھاؤ۔ سیدنا سلمان رضی اللہ عنہ کہنے لگے: یہ ایک نشانی ہوئی۔ واپس آگئے۔ اس کے بعد کچھ دن ٹھہر کر انھوں نے پھر کچھ کھجوریں جمع کیں اور رسول اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ عرض کرنے لگے: آپ چونکہ صدقہ نہیں کھاتے، اس لیے یہ کھجوریں میں بطور ہدیہ (تحفہ) لایا ہوں۔ اس میں سے آپ صلی اللہ علیہ وسلم نے خود بھی کھائیں اور صحابہ کو بھی کھانے کا حکم دیا۔ سلمان رضی اللہ عنہ نے کہا: یہ دوسری نشانی ہوئی۔ سلمان رضی اللہ عنہ فرماتے ہیں: تیسری بار جب میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں تیسری نشانی (مہر نبوت) دیکھنے کے لیے آیا تو آپ بقیع الغرقد قبرستان میں کسی جنازے میں شریک تھے (غالباً یہ سیدنا عثمان بن مظعون رضی اللہ عنہ کا جنازہ تھا۔) رسول اللہ صلی اللہ علیہ وسلم کے گرد صحابہ بھی تشریف فرما تھے۔ میں نے سلام کیا اور آپ کے اردگرد گھومنے لگا۔ آپ نے میرا مقصد جان کر اپنی چادر مبارک کندھوں سے سرکا دی۔ میں نے ختم نبوت (مہر نبوت) دیکھی۔ یہ آخری نشانی دیکھ کر میں رونے لگا۔ آپ نے مجھے روتے دیکھا تو اپنے سامنے بٹھا لیا اور میری کہانی سنی۔ اس سے آپ بہت خوش ہوئے۔","",{"v":400316,"fn":"(1) السيرة النبوية في ضوء القرآن والسنة: 21/2، تاريخ الطبري: 115/2"}],[1907,"ان واقعات سے معلوم ہوتا ہے کہ سلمان رضی اللہ عنہ آغاز ہجرت میں مسلمان ہو چکے تھے۔ جنگ بدر اور احد غلامی کی حالت میں گزر گئیں، اس لیے شرکت نہ کر سکے۔ پہلا معرکہ جس میں سلمان رضی اللہ عنہ شریک ہوئے، جنگ خندق ہے جو انھی کے مشورے سے خندق کھود کر لڑی گئی تھی۔(1)\n§سیدنا عبداللہ بن سلام رضی اللہ عنہ کا قبول اسلام\nامام ابن کثیر رحمہ اللہ سیدنا عبداللہ بن سلام رضی اللہ عنہ کے اسلام کے بارے میں ذکر کرتے ہیں کہ سیدنا عبداللہ بن سلام رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے پہلی ملاقات قباء میں کی۔ امام ترمذی اور ابن ماجہ رحمہما اللہ کے سیاق سے بھی یہی معلوم ہوتا ہے کہ انھوں نے نبی کریم صلی اللہ علیہ وسلم کا سب سے پہلے جو فرمان سنا اور آپ صلی اللہ علیہ وسلم کو دیکھا، وہ قباء ہی کی بات ہے۔\nامام ابن کثیر رحمہ اللہ لکھتے ہیں کہ سیدنا عبداللہ بن سلام رضی اللہ عنہ نے فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم مدینہ تشریف لائے اور میں نے آپ کے چہرہ مبارک کو دیکھا تو پہچان گیا کہ یہ چہرہ ہرگز جھوٹے شخص کا نہیں۔ میں نے سنا، آپ فرما رہے تھے:\n«أَفْشُوا السَّلَامَ، وَأَطْعِمُوا الطَّعَامَ، وَصِلُوا الْأَرْحَامَ، وَصَلُّوا بِاللَّيْلِ وَالنَّاسُ نِيَامٌ، تَدْخُلُوا الْجَنَّةَ بِسَلَامٍ»\n’’تم سلام کو عام کرو، کھانا کھلاؤ، صلہ رحمی کرو اور رات کو نماز پڑھو جب لوگ سو رہے ہوں، تم سلامتی کے ساتھ جنت میں داخل ہو جاؤ گے۔‘‘\nاس سیاق کا بھی تقاضا یہ ہے کہ عبداللہ بن سلام رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کا یہ فرمان قباء ہی میں سنا ہو اور وہیں آپ کو پہلی بار دیکھا ہو جبکہ آپ بنی عمرو بن عوف کے ہاں قیام فرما تھے۔\nعبدالعزیز بن صہیب رحمہ اللہ نے سیدنا انس رضی اللہ عنہ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ میں جب سیدنا ابو ایوب رضی اللہ عنہ کے ہاں پہنچے تو وہاں عبداللہ بن سلام رضی اللہ عنہ تشریف لائے اور اسلام قبول کیا۔ اسی موقع پر عبداللہ بن سلام نے نبی صلی اللہ علیہ وسلم سے مشہور تین سوال کیے تھے اور نبی صلی اللہ علیہ وسلم نے ان کے بارے میں یہود سے استفسار کیا تھا۔(2)\n§اہل مدینہ کا اشتیاق اور ابن ابی کی ہٹ دھرمی\nموسیٰ بن عقبہ رحمہ اللہ نے ذکر کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم راستے میں عبداللہ بن ابی ابن سلول کے پاس سے","",{"v":400317,"fn":"(1) دیکھیے: الاستیعاب، أسد الغابة، الإصابة\n(2) دیکھیے: البداية والنهاية: 198-208/3"}],[1908,"گزرے۔ وہ اس وقت اپنے ایک گھر میں تھا۔ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو کر انتظار کرنے لگے کہ وہ آپ کو گھر کے اندر بلائے۔ ان دنوں وہ خزرج کا سردار تھا۔ عبداللہ بن ابی نے کہا: ان لوگوں کے پاس جاؤ جنھوں نے تمھیں بلایا ہے۔ ان کے پاس جا کر ٹھہرو۔ آپ صلی اللہ علیہ وسلم نے یہ بات چند انصاری صحابہ سے کہی تو سعد بن عبادہ رضی اللہ عنہ اس کی طرف سے معذرت پیش کرتے ہوئے کہنے لگے: یا رسول اللہ! اللہ نے آپ کو بھیج کر ہم پر احسان کیا ہے۔ ہم عنقریب ہی اس کے سر پر تاج رکھ کر اسے اپنا بادشاہ بنانے والے تھے۔(1)\nموسیٰ بن عقبہ رحمہ اللہ کہتے ہیں: انصار مدینہ رسول اللہ صلی اللہ علیہ وسلم کے بنی عمرو بن عوف کے ہاں سے روانہ ہونے سے پہلے جمع ہو چکے تھے۔ سب آپ کی اونٹنی کے گرد چلنے لگے۔ ان میں سے ہر ایک رسول اللہ صلی اللہ علیہ وسلم کی تکریم و تعظیم کی کوشش کر رہا تھا کہ وہ اونٹنی کی لگام تھامے۔ آپ صلی اللہ علیہ وسلم جب کسی انصاری کے گھر کے پاس سے گزرتے تو وہ آپ کو اپنے گھر کے اندر تشریف لانے کی درخواست کرتا۔ آپ صلی اللہ علیہ وسلم فرماتے: ’’اونٹنی کو چھوڑ دو، یہ اللہ کے حکم کی پابند ہے۔ میں وہیں ٹھہروں گا، جہاں مجھے اللہ ٹھہرائے گا۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم کے پاس عتبان بن مالک اور عباس بن عبادہ بن نضلہ رضی اللہ عنہم بنی سالم کے دیگر کچھ لوگوں کے ساتھ آئے اور کہا: یا رسول اللہ! آپ ہمارے پاس قیام کیجیے۔ ہم نفری، قوت، اسلحہ اور ساز و سامان والے لوگ ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم لوگ اونٹنی کا راستہ چھوڑ دو، یہ اللہ کی طرف سے مامور ہے۔‘‘ تو وہ لوگ ہٹ گئے اور اونٹنی چلتی ہوئی جب بنی بیاضہ کے محلے میں آئی تو بنی بیاضہ کے لوگوں میں سے زیاد بن لبید اور فروہ بن عمرو آپ صلی اللہ علیہ وسلم سے ملے۔ یہ لوگ بھی کہنے لگے: یا رسول اللہ! آپ ہمارے پاس تشریف لائیں۔ ہم نفری، قوت، اسلحہ اور ساز و سامان والے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم لوگ اونٹنی کا راستہ چھوڑ دو، یہ اللہ کی طرف سے مامور ہے۔‘‘ وہ لوگ اس کے راستے سے ہٹ گئے۔\nاونٹنی پھر چل پڑی یہاں تک کہ بنی ساعدہ کے محلے سے گزری۔ یہاں سعد بن عبادہ اور منذر بن عمرو بنو ساعدہ کے افراد کے ساتھ رسول اللہ صلی اللہ علیہ وسلم سے ملنے آئے۔ لوگ بھی کہنے لگے: یا رسول اللہ! آپ ہمارے پاس تشریف لائیں، ہماری تعداد بڑی ہے اور ہم آپ کی حفاظت کی طاقت رکھتے ہیں۔\n[تصویر: محلہ بنی ساعدہ (ماضی کا منظر)]","",{"v":400318,"fn":"(1) دلائل النبوة للبيهقي: 499/2","im":["v4_p318.jpg"]}],[1909,"آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم لوگ اس اونٹنی کا راستہ چھوڑ دو، یہ اللہ کی طرف سے مامور ہے۔‘‘ تو وہ الگ ہٹ گئے۔ اونٹنی آگے چل پڑی یہاں تک کہ بنی حارث بن خزرج کے محلے میں پہنچی۔ بنو حارث بن خزرج کے افراد کے ساتھ سعد بن ربیع، خارجہ بن زید اور عبداللہ بن رواحہ رضی اللہ عنہم ملاقات کے لیے آئے اور آگے بڑھ کر عرض گزار ہوئے: یا رسول اللہ! آپ ہمارے پاس تشریف لائیں۔ ہم تعداد، ہتھیار اور قوت دفاع میں زیادہ ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس کا راستہ چھوڑ دو، یہ اللہ کے حکم کی پابند ہے۔‘‘ لوگوں نے اس کا راستہ چھوڑ دیا۔\nاونٹنی آگے چل پڑی یہاں تک کہ عدی بن نجار کے محلے میں پہنچی۔ یہ رسول اللہ صلی اللہ علیہ وسلم کے ننھیالی لوگ تھے، اس لیے کہ سردار عبدالمطلب کی والدہ سلمیٰ بنت عمرو انھی لوگوں کی بیٹی تھی۔ عدی بن نجار کے لوگوں کے ساتھ سلیط بن قیس اور ابو سلیط اسیرہ بن ابو خارجہ آپ صلی اللہ علیہ وسلم سے راستے میں ملے۔ یہ لوگ آگے بڑھ کر پیش کش کرتے ہیں: یا رسول اللہ! آپ اپنی ننھیال کے پاس تشریف لائیے۔ ہم لوگ تعداد، اسباب جنگ اور دفاعی قوت میں زیادہ ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس کا راستہ چھوڑ دو، یہ اللہ کے حکم کی پابند ہے۔‘‘ لوگوں نے اس کا راستہ چھوڑ دیا۔\nاونٹنی چلتی ہوئی جب بنی مالک بن نجار کے محلے میں پہنچی تو آج کی مسجد نبوی کے دروازے کے پاس بیٹھ گئی۔ اس وقت وہ جگہ کھلیان کے طور پر استعمال ہوتی تھی اور بنی مالک بن نجار کے دو یتیم لڑکوں سہل اور سہیل رضی اللہ عنہما کی ملکیت تھی۔ یہ دونوں معاذ بن عفراء رضی اللہ عنہ کی گود میں پلے بڑھے تھے۔ بخاری کی ایک روایت میں ہے کہ دونوں اسعد بن زرارہ رضی اللہ عنہ کی گود میں پلے بڑھے تھے۔(1) واللہ اعلم۔\n§ابو ایوب رضی اللہ عنہ کے گھر میں قیام\nابن اسحاق رحمہ اللہ کہتے ہیں: اونٹنی جب وہاں بیٹھی تو آپ صلی اللہ علیہ وسلم اس سے اترے نہیں، وہ پھر دوبارہ کھڑی ہوگئی اور تھوڑی دور تک گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کی لگام ڈھیلی چھوڑ دی تھی۔ اونٹنی پھر پیچھے کی طرف مڑی اور جہاں پہلی بار بیٹھی تھی وہیں لوٹ آئی اور دوبارہ اسی جگہ بیٹھ گئی، پھر اونٹنی نے آواز نکالی اور آرام کے ساتھ وہیں بیٹھ گئی، تب آپ صلی اللہ علیہ وسلم اتر آئے اور ابو ایوب خالد بن زید رضی اللہ عنہ نے آپ کا سامان سفر اتار کر اپنے گھر میں رکھا اور رسول اللہ صلی اللہ علیہ وسلم وہاں قیام پذیر ہو گئے۔\nرسول اللہ صلی اللہ علیہ وسلم نے کھلیان کے بارے میں پوچھا: یہ کس کا ہے؟ معاذ بن عفراء رضی اللہ عنہ نے کہا: اے اللہ کے رسول! یہ عمرو کے بیٹوں سہل اور سہیل رضی اللہ عنہما کا ہے۔ یہ دونوں یتیم میری نگرانی میں ہیں اور میں ان دونوں کو یہ زمین دینے","",{"v":400319,"fn":"(1) السيرة النبوية لابن كثير، ص: 216,217، السيرة لابن هشام: 494,495/2، صحيح البخاري: 3906"}],[1910,"کے لیے راضی کر لوں گا، آپ یہاں مسجد بنا لیجیے گا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے تعمیر مسجد کا حکم دے دیا۔(1)\nامام بیہقی رحمہ اللہ نے دلائل النبوہ میں لکھا ہے: جب اونٹنی ابو ایوب رضی اللہ عنہ کے دروازے کے سامنے بیٹھ گئی تو بنی نجار کی کچھ چھوٹی لڑکیاں دف بجاتی ہوئی اور یہ کہتی ہوئی نکلیں:\nنَحْنُ جَوَارٍ مِّنْ بَنِي النَّجَّارِ يَا حَبَّذَا مُحَمَّدٌ مِّنْ جَارِ\n’’ہم بنی نجار کی لڑکیاں ہیں، محمد ہمارے کتنے اچھے پڑوسی بن گئے ہیں۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم ان کے پاس آئے اور فرمایا: ’’کیا تم مجھ سے محبت کرتے ہو؟‘‘ انھوں نے کہا: ہاں، اللہ کی قسم! اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! میں بھی تم سب سے محبت کرتا ہوں۔‘‘ آپ صلی اللہ علیہ وسلم نے یہ جملہ تین بار دہرایا۔\nصحیح بخاری میں انس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انصار کی عورتوں اور بچوں کو کسی شادی سے واپس آتے دیکھا تو رسول اللہ صلی اللہ علیہ وسلم ان کے سامنے کھڑے ہو گئے اور فرمایا: «اللَّهُمَّ! أَنْتُمْ مِنْ أَحَبِّ النَّاسِ إِلَيَّ» قَالَهَا ثَلَاثَ مَرَّاتٍ. ’’اللہ گواہ ہے کہ تم لوگ مجھے مخلوق میں سب سے زیادہ محبوب ہو۔‘‘ آپ صلی اللہ علیہ وسلم نے یہ بات تین بار کہی۔(2)\nامام ابن اسحاق رحمہ اللہ نے سیدنا ابو ایوب رضی اللہ عنہ سے روایت کی ہے، وہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم میرے گھر میں رہنے لگے تو آپ نیچے ٹھہرے اور میں اور ام ایوب بالائی منزل پر۔ میں نے آپ صلی اللہ علیہ وسلم سے گزارش کی: میرے ماں باپ آپ پر فدا ہوں! مجھے اچھا نہیں لگتا کہ میں آپ کے اوپر رہوں اور آپ میرے نیچے، اس لیے آپ اوپر تشریف لے چلیں اور ہم نیچے آجاتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے ابو ایوب! ہمارے لیے اور ہمارے پاس آنے والوں کے لیے مناسب یہی ہے کہ میں نیچے رہوں۔‘‘ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نیچے رہنے لگے اور ہم اوپر۔ ایک دن اوپر ہمارے پانی کا ایک مٹکا ٹوٹ گیا۔ میں اور ام ایوب فوراً اپنا ایک کمبل لے کر پانی کو خشک کرنے لگے، ہمارے پاس اس کے سوا کوئی لحاف نہ تھا، تاکہ پانی کا کوئی حصہ آپ کے اوپر ٹپک کر آپ کی تکلیف کا سبب نہ بنے۔\nسیدنا ابو ایوب رضی اللہ عنہ کہتے ہیں: ہم آپ صلی اللہ علیہ وسلم کے لیے رات کا کھانا تیار کر کے آپ کے پاس بھیج دیتے تھے اور جب آپ اس کا باقی ماندہ حصہ واپس کرتے تو میں اور ام ایوب آپ کے ہاتھ کے نشان کی جگہ سے لے کر بطور تبرک کھایا کرتے۔ ایک رات ہم نے آپ کو کھانا بھیجا جس میں پیاز یا لہسن ملا تھا۔ آپ صلی اللہ علیہ وسلم نے اسے جب واپس کیا","",{"v":400320,"fn":"(1) السيرة لابن هشام: 496/2\n(2) صحيح البخاري: 3785"}],[1911,"تو اس میں ہم نے آپ صلی اللہ علیہ وسلم کے ہاتھ کا نشان نہیں پایا۔ میں گھبرایا ہوا آپ کے پاس آیا اور پوچھا: اے اللہ کے رسول! میرے ماں باپ آپ پر فدا ہوں! آپ نے کھانا واپس کر دیا اور اس میں ہم نے آپ کے ہاتھ کا نشان نہیں دیکھا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے اس کھانے میں اس درخت (پیاز یا لہسن) کی بو آئی تھی اور میں (جبریل سے) سرگوشی کرتا ہوں۔ اس لیے تم لوگ وہ کھانا کھا لو، چنانچہ وہ کھانا ہم لوگوں نے کھا لیا اور پھر اس کے بعد کبھی آپ کے کھانے میں پیاز یا لہسن نہیں ڈالا۔‘‘(1)\nسیدنا زید بن ثابت رضی اللہ عنہ سے مروی ہے، انھوں نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم ابو ایوب رضی اللہ عنہ کے گھر مہمان بنے تو پہلا ہدیہ جو آپ صلی اللہ علیہ وسلم کے لیے آیا، وہ دودھ، گھی اور روٹی سے تیار کردہ ثرید کا پیالہ تھا۔ میں نے آپ صلی اللہ علیہ وسلم سے کہا: یہ میری ماں نے بھیجا ہے۔ آپ صلی اللہ علیہ وسلم نے برکت کی دعا کی اور اپنے اصحاب کو بلا کر سب کے ساتھ اسے کھایا، پھر دوسرا پیالہ سعد بن عبادہ رضی اللہ عنہ کے گھر سے آیا جس میں ثرید اور گوشت تھا۔ اس طرح ہر رات آپ صلی اللہ علیہ وسلم کے دروازے پر تین چار آدمی باری باری کھانا لے کر آتے۔ آپ صلی اللہ علیہ وسلم کا قیام ابو ایوب رضی اللہ عنہ کے گھر میں سات ماہ تک رہا۔(2)\nہجرت نبوی کی ان مذکورہ تفاصیل سے معلوم ہوا کہ مکہ سے نکلنے کے بعد مدینہ پہنچنے تک آپ صلی اللہ علیہ وسلم کو پندرہ دن لگے تھے۔ ابن عباس رضی اللہ عنہما سے ثابت ہے کہ آپ صلی اللہ علیہ وسلم مکہ سے سوموار کے دن نکلے تھے اور مدینہ سوموار کے دن بارہ ربیع الاول کو پہنچے تھے اور مدینہ میں آپ صلی اللہ علیہ وسلم دس سال رہے۔(3) غار ثور میں تین دن تک چھپے رہے۔ وہاں سے نکل کر ساحل کے راستے سے جو عام راستے سے طویل ہے، قبا پہنچے تھے۔\n§ہجرت کی گزرگاہیں\nنبی مکرم محمد صلی اللہ علیہ وسلم جن جن راہوں، وادیوں اور علاقوں سے گزر کر مدینہ منورہ پہنچے، ان علاقوں کا مختصر سا تعارف فائدے سے خالی نہیں تاکہ پتہ چل جائے کہ ہمارے پیارے نبی صلی اللہ علیہ وسلم نے کیسے کیسے نشیب و فراز عبور کیے اور اللہ کی رضا کی خاطر کتنے کٹھن حالات و حوادث کا مقابلہ کیا۔\nنبی صلی اللہ علیہ وسلم سیدنا علی بن ابی طالب رضی اللہ عنہ کو اپنے بستر پر سلا کر اپنے گھر سے نکلتے ہیں اور سیدنا ابو بکر صدیق رضی اللہ عنہ کے گھر (مسفلہ) کی جانب پہنچتے ہیں۔ ان کے گھر کے عقبی دروازے سے نکل کر جبل ثور پہنچتے ہیں۔ جبل ثور سے نکل","",{"v":400321,"fn":"(1) صحيح مسلم: 2053، السيرة لابن هشام: 498,499/2، السيرة النبوية لابن كثير، ص: 217\n(2) السيرة النبوية لابن كثير، ص: 217,218\n(3) المعجم الكبير للطبراني: 173/17، علامہ ہیثمی نے اس کے راویوں کو ثقہ قرار دیا ہے۔ مجمع الزوائد: 63/6"}],[1912,"[تصویر: نقشہ: نبی صلی اللہ علیہ وسلم کا سفر ہجرت (مکہ تا مدینہ)]\nنبی صلی اللہ علیہ وسلم کا سفر ہجرت (مکہ تا مدینہ)\n﴿وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ ۖ وَاللَّهُ خَيْرُ الْمَاكِرِينَ﴾ ’’اور یاد کیجیے! جب تدبیر کر رہے تھے آپ کی بابت وہ لوگ جنھوں نے کفر کیا تاکہ وہ قید کر دیں آپ کو، یا قتل کر دیں آپ کو، یا نکال دیں آپ کو اور تدبیریں کر رہے تھے وہ اور تدبیر کر رہا تھا اللہ بھی، اور اللہ سب سے بہتر تدبیر کرنے والا ہے۔‘‘ (الأنفال 8:30)\n﴿إِلَّا تَنْصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا ۖ فَأَنْزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْهَا﴾ ’’اگر نہ مدد کرو گے تم اس کی تو تحقیق مدد کی اس (پیغمبر) کی اللہ نے جب کہ نکال دیا تھا اس کو ان لوگوں نے جنھوں نے کفر کیا (وہ) دوسرا تھا دو میں سے جب وہ دونوں تھے غار میں جب کہ وہ کہہ رہا تھا اپنے ساتھی سے غم نہ کر بیشک اللہ ہمارے ساتھ ہے پس نازل کی اللہ نے اپنی سکینت اس پر اور مدد کی اس کی ایسے لشکروں سے کہ نہیں دیکھا تم نے ان کو‘‘ (التوبة 9:40)\nاشارات: ہجرت نبوی کا راستہ؛ قافلوں کا راستہ\nحجاز، بحیرہ قلزم (احمر)، مکہ مکرمہ، جبل ثور، عسفان، قدید، خیمہ ام معبد، رابغ، جحفہ، ابواء، بدر، مدینہ منورہ، قباء، جدہ","",{"v":400322,"im":["v4_p322.jpg"]}],[1913,"کر مدینہ شاہراہ عام سے ہٹ کر وادی عسفان کے نشیب کی جانب جاتے ہیں جو بنو مصطلق خزاعی کا علاقہ تھا۔ یہاں وافر تعداد میں چشمے اور تالاب تھے۔ اس کو عسفان اس لیے کہا گیا کہ یہاں سیلابی ریلا جمع ہوتا تھا۔ ایک جانب مکہ اور دوسری جانب جدہ کا بارانی پانی یہاں جمع ہوتا تھا۔ عسفان مکہ سے 80 میل کے فاصلے پر واقع ہے۔\n[تصویر: وادی عسفان میں پانی کا اہتمام]\nنبی صلی اللہ علیہ وسلم عسفان کے بعد بنی سلیم کے علاقے وادی غران کی جانب وادی امج کے نشیب میں پہنچے۔ وادی امج مکہ سے 100 کلومیٹر شمال میں شاہراہ عام پر ایک شاداب وادی ہے۔ آج کل قصبہ امج خلیص کے نام سے معروف ہے۔ وادی امج بنو خزاعہ کا علاقہ شمار ہوتا تھا۔ ان کے ہاں کھجوروں کے باغات، کھیتیاں اور چشمے تھے۔ یہاں بنو سلیم کے لوگ بھی رہتے تھے۔ مکہ کی جانب سے خلیص کے دو میل بعد وادی امج واقع ہے۔ وادی امج کے ایک میل بعد وادی غران ہے۔ یہ دونوں وادیاں (وادی امج اور وادی نخلہ) غران حرہ بنو سلیم سے نکل کر سمندر میں جا گرتی ہیں۔\n[تصویر: وادی امج کا نشیب]\nنبی صلی اللہ علیہ وسلم وادی امج سے نکل کر وادی قدید پہنچے جو شارع عام سے بالکل ہٹی ہوئی تھی اور امج سے تقریباً ایک منزل کی مسافت پر واقع تھی۔ قدید وادی کے نام پر ایک چھوٹا قصبہ ہے۔ یہ آج بھی اسی نام سے موسوم ہے اور مکہ سے رابغ شہر جاتے ہوئے راستے ہی میں واقع ہے۔\n[تصویر: وادی خلیص کا ایک منظر]\nخلیص اور قدید کے درمیان آٹھ میل کا فاصلہ ہے۔ یہ علاقہ بھی بنو خزاعہ کا تھا۔ یہاں پانی کا ایک چشمہ تھا اور قدید زرخیز وادی تھی۔ اسی وادی کا بالائی حصہ ستارہ اور زیریں حصہ قدید کہلاتا ہے۔ یہ وادی مکہ مدینہ شاہراہ کو تقریباً 120 کلومیٹر پر کاٹتی ہوئی قضیمہ کے پاس سمندر میں جا گرتی ہے۔ ابن الکلبی کا کہنا ہے جب تبع یمن اہل مدینہ کے ساتھ لڑائی کرنے کے بعد یہاں پہنچا تو یہاں آ کر خیمہ زن ہوا۔ یہاں سخت آندھی چلی جس نے اس کے ہمراہیوں کے\n[تصویر: وادی غران]","",{"v":400323,"im":["v4_p323.jpg"]}],[1914,"خیموں کو الٹ دیا۔ اسی وجہ سے یہ جگہ قدید کے نام سے مشہور ہوئی۔ نبی صلی اللہ علیہ وسلم غزوہ مریسیع کو جاتے ہوئے بھی یہاں قدید سے گزرے تھے۔ وادی قدید کے بعد ہجرت نبوی کا قافلہ الخرار پہنچا۔ قصبہ الخرار رابغ کے مشرق میں تقریباً 25 کلومیٹر کے فاصلے پر ہے۔ الخرار ایک وادی ہے جسے غدیر خم کا نام بھی دیا جاتا ہے۔ الجحفہ اور غدیر خم کے مابین دو میل کی مسافت ہے۔ ۱ وادی غدیر خم میں خزاعہ اور کنانہ کے لوگ آباد ہیں۔ اس کے پاس نبی صلی اللہ علیہ وسلم نے یمن کے وفد کو خطاب بھی فرمایا تھا۔\n[تصویر: قریہ وادی قدید]\nالخرار کے بعد نبی صلی اللہ علیہ وسلم ثنیۃ المرۃ کے پاس سے گزرے۔ آج کل یہ غدیر خم اور الفرع کے درمیان معروف ہے۔ اس کے بعد نبی صلی اللہ علیہ وسلم لقف کے نزدیک سے گزرے۔ اسے لفت بھی کہا گیا ہے۔ یاقوت نے کہا ہے کہ لقف اور لفت دونوں مکہ اور مدینہ کے درمیان الگ الگ مقامات ہیں۔\n[تصویر: وادی رابغ]\nاس کے بعد آپ صلی اللہ علیہ وسلم مجاح کے بیابان سے گزرے۔ اس کے بعد یہ قافلہ مجاح کے موڑ سے گزرا، پھر ذوالعضوین کے موڑ کے نشیب میں چلا، پھر ذی کشر وادی میں داخل ہوا۔ اس کے بعد جداجد کا رخ کیا۔ یہ جدجد کی جمع ہے۔ پرانے کنویں کو جدجد کہا جاتا ہے۔ یاقوت کہتے ہیں کہ یہاں پرانے زمانے کے بہت سے کنویں تھے جنھیں جداجد کہا جاتا تھا۔\n[تصویر: وادی الخرار (غدیر خم)]\nیہاں سے آپ صلی اللہ علیہ وسلم کا قافلہ اجرد پہنچا۔ اجرد ایک پہاڑ کا نام ہے۔ یہاں قبیلہ بنو جہینہ آباد تھا۔ یہ مدینہ سے شام کے راستے میں آتا ہے۔ اس کے بعد آپ صلی اللہ علیہ وسلم وادی ذو سلم سے گزرے، یہ وادی بیابان تعہن کے اطراف میں ہے۔ تعہن ایک چشمہ تھا۔ یہ اشقیا سے تین میل کے فاصلے پر واقع ہے۔ اشقیا، ابواء سے انیس میل کے فاصلے پر ہے۔\nیہاں سے آپ صلی اللہ علیہ وسلم کا قافلہ العبابیہ یا العبابیب سے گزرا جو تعہن سے\n[تصویر: وادی القف کا ایک منظر]\n۱ معجم البلدان، مادہ: الجحفة","",{"v":400324,"im":["v4_p324.jpg"]}],[1915,"قریب ہے۔ یہ السقیا سے ایک میل کے فاصلے پر واقع ہے۔ اس کے بعد کاروانِ ہجرت الفاجہ سے گزرا۔ اسے القاحہ بھی پڑھا گیا ہے۔ یہ مدینہ منورہ سے السقیا کی جانب تین مراحل کی مسافت پر واقع ہے اور السقیا سے ایک میل کے فاصلے پر ہے۔ یاقوت نے کہا ہے کہ القاحہ یا الفاجہ ایک پہاڑ کا نام ہے۔ اس کے بعد نبی اکرم صلی اللہ علیہ وسلم عرج پہنچے جہاں اوس بن حجر اسلمی سے ملاقات ہوئی۔ عرج کے بعد آپ صلی اللہ علیہ وسلم ثنیۃ العائر سے گزرے۔ اس کے بعد رئم سے گزرے جو مدینہ کے قریب مزینہ کی وادی تھی۔ بعض نے کہا ہے کہ یہ مدینہ سے تیس میل کے فاصلے پر تھی۔ رئم کے بعد نبی صلی اللہ علیہ وسلم قباء پہنچے جو نبی صلی اللہ علیہ وسلم کی پہلی جائے قیام تھی۔(1)\n§رسول اللہ صلی اللہ علیہ وسلم کے اہل خانہ کی ہجرت\nرسول اللہ صلی اللہ علیہ وسلم جب مدینہ گئے تو آپ نے اپنے اہل و عیال کو مکہ سے لانے کے لیے سیدنا زید بن حارثہ اور ابو رافع رضی اللہ عنہما کو بھیجا کہ وہ آپ صلی اللہ علیہ وسلم کی بیٹیوں اور زوجہ مطہرہ سیدہ سودہ بنت زمعہ رضی اللہ عنہا کو لے آئیں۔ آپ نے دو اونٹ اور سیدنا ابوبکر رضی اللہ عنہ سے پانچ سو درہم لے کر ان کے سپرد کیے تاکہ واپسی پر ضرورت کے مطابق سواریاں خریدی جا سکیں۔\nابوبکر رضی اللہ عنہ نے بھی ان دونوں کے ساتھ ہی عبداللہ بن اریقط دیلی کو دو یا تین اونٹ دے کر روانہ کیا، نیز عبداللہ بن ابوبکر رضی اللہ عنہ کو خط لکھا کہ وہ ان کی اہلیہ ام رومان، بیٹی عائشہ اور اسماء، جو زبیر بن عوام کی زوجہ تھیں، کو بھی ساتھ لے آئیں۔ یہ لوگ صبح صبح مدینہ سے چلے اور مقام قدید پر جا کر سیدنا زید رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے دیے ہوئے پانچ سو درہموں سے تین سواریاں خریدیں۔ یہ لوگ مکہ داخل ہوئے تو پتہ چلا کہ طلحہ بن عبید اللہ آل ابوبکر کے ساتھ ہجرت کرنا چاہتے ہیں۔ یوں سب لوگوں نے یکبارگی ہجرت کی۔ اس کی تفصیل یوں ہے کہ ابو رافع رضی اللہ عنہ فاطمہ، ام کلثوم اور سودہ بنت زمعہ رضی اللہ عنہا کو لے کر آ گئے۔ زید رضی اللہ عنہ نے ام ایمن اور اسامہ بن زید کو سوار کر لیا اور عبداللہ بن ابوبکر رضی اللہ عنہ کے ساتھ ام رومان اور اس کی دونوں بیٹیاں تھیں۔ طلحہ بن عبید اللہ اکیلے تھے، بعد میں سب اکٹھے ہو گئے۔ پھر یہ لوگ چلتے چلتے مدینہ آ گئے۔(2)\n§مہاجرین کی فضیلت\nہجرت مدینہ اسلامی دعوت کی تاریخ کا نہایت عظیم الشان سنگ میل ہے۔ اس ہجرت سے مسلمانوں کی کایا پلٹ گئی۔ اس سے پہلے مسلمانوں کی اجتماعی حیثیت واضح نہیں تھی، نہ کوئی ایسا مقام تھا جو مسلمانوں کا تحفظ اور دشمن","",{"v":400325,"fn":"(1) ملخص از طریق الہجرۃ النبویۃ لعبد القدوس الأنصاري، ص: 62-88\n(2) المستدرك للحاكم: 4,5/4، تاريخ الطبري: 118,119/2"}],[1916,"کے مقابلے میں ان کا دفاع کرتا۔\nہجرت کے بعد جب اسلامی ریاست کا قیام عمل میں آیا تو اسلام جزیرہ نمائے عرب کے اندرونی اور بیرونی علاقوں میں تیزی سے پھیلتا چلا گیا۔ داعیان اسلام آس پاس کے علاقوں میں جاتے اور دعوت دین کا فریضہ انجام دیتے تھے۔ اس طرح اسلام کو عالمگیر حیثیت نصیب ہوئی اور توحید و رسالت کے نور مبین کا ڈنکا پوری دنیا میں بجنے لگا۔ اللہ تعالیٰ نے مہاجرین کی عظمت و شان کو بڑے بلیغ انداز میں سراہا ہے اور انھیں فوقیت و فضیلت سے نوازا ہے۔ فرمان الہی ہے:\n﴿وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ وَالَّذِينَ اتَّبَعُوهُم بِإِحْسَانٍ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ وَأَعَدَّ لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ۚ ذَٰلِكَ الْفَوْزُ الْعَظِيمُ ۝﴾\n’’اور مہاجرین اور انصار میں سے (قبول اسلام میں) سب سے پہلے سبقت کرنے والے اور وہ لوگ جنھوں نے (احسان) اچھے طریقے کے ساتھ ان کی پیروی کی، اللہ ان سے راضی ہو گیا اور وہ اس (اللہ) سے راضی ہو گئے اور اس (اللہ) نے ان کے لیے ایسے باغات تیار کیے ہیں جن کے نیچے نہریں بہتی ہیں، وہ ان میں ہمیشہ ہمیشہ رہیں گے، یہ بہت بڑی کامیابی ہے۔‘‘(1)\nاس آیت کریمہ میں مہاجرین کی فضیلت ان کی سبقت کی بنا پر ہے۔ اس کے علاوہ اللہ تعالیٰ نے مہاجرین کو ایسی منفرد صلاحیتوں سے نوازا تھا جن کی بدولت انھوں نے ہر قسم کے دباؤ، آزمائش، بھوک اور غریب الوطنی جیسی تکالیف کو ہنسی خوشی برداشت کیا یہاں تک کہ موت کو بھی گلے لگا لیا۔ یوں مدینہ میں اسلام کو نہایت ٹھوس بنیادیں فراہم ہوئیں۔ عام انصار اگرچہ مہاجرین کے بعد دائرہ اسلام میں آئے تھے لیکن ان کی بیعت عقبہ میں شمولیت سے معلوم ہوتا ہے کہ ان کی طبیعتیں بھی خالص اور کھری تھیں جو اس دین کے مزاج سے ہم آہنگ تھیں۔\nمہاجرین و انصار کے باہمی تعلق و ارتباط سے اسلامی معاشرے کے لیے ایسی ٹھوس بنیاد تشکیل پائی جس کے قوام میں عربی معاشرے کے مضبوط اور مستحکم ترین اصول شامل تھے۔ دین اسلام کا معاملہ کھلی کتاب کے مانند تھا۔ جاہلیت سے نکل کر دائرہ اسلام میں آنے اور اس دشوار گزار راستے کو طے کرنے کی ہمت وہی جاں نثار کرتے تھے جو غیر معمولی مضبوط مزاج اور مصمم ارادے کے مالک ہوتے تھے۔(2)\nقرآن کریم میں مہاجرین کا ایک وصف یہ بھی بتایا گیا ہے کہ ان کے ایمان میں بڑی سچائی تھی اور جن حضرات","",{"v":400326,"fn":"(1) التوبة 9:100\n(2) تفسير في ظلال القرآن لسيد قطب: 1703/3"}],[1917,"نے انھیں ٹھکانا دیا، وہ بھی سچے مومن تھے۔ اللہ تعالیٰ نے ارشاد فرمایا:\n﴿وَالَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوْا وَّنَصَرُوا أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا ۚ لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ ۝﴾\n’’اور جو لوگ ایمان لائے اور انھوں نے ہجرت کی اور اللہ کی راہ میں جہاد کیا اور جنھوں نے (مہاجرین کو) ٹھکانا دیا اور (ان کی) مدد کی، وہی لوگ سچے مومن ہیں، ان کے لیے بخشش اور باعزت روزی ہے۔‘‘(1)\nیہ اللہ علیم و خبیر کی شہادت ہے کہ مہاجرین سچے مومن تھے جو نبی صلی اللہ علیہ وسلم کے بعد ساری امت کے لیے نمونۂ عمل کی حیثیت اختیار کر گئے۔ انھی صفات کی بدولت وہ اللہ تعالیٰ کی مدح کے مستحق ٹھہرے کہ دراصل یہی مومن ہیں۔ یہ صفات مہاجرین کی زندگیوں میں بہت واضح نظر آتی ہیں اور انھی صفات کے حامل لوگ ہی حقیقی اہل ایمان ہیں۔\nقرآن کریم میں مہاجرین کی دیگر اہم صفات کا تذکرہ ان الفاظ میں کیا گیا ہے:\n﴿لِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِن دِيَارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ اللَّهِ وَرِضْوَانًا وَيَنصُرُونَ اللَّهَ وَرَسُولَهُ ۚ أُولَٰئِكَ هُمُ الصَّادِقُونَ ۝﴾\n’’(مال فے) ان فقیر مہاجرین کے لیے ہے جو اپنے گھروں اور اپنی جائیدادوں سے نکالے گئے، وہ اللہ کا فضل اور اس کی رضامندی کے متلاشی ہیں اور اللہ اور اس کے رسول کی مدد کرتے ہیں، یہی سچے لوگ ہیں۔‘‘(2)\nاس آیت کریمہ میں اللہ تبارک و تعالیٰ نے مہاجرین کی کئی صفات کا ذکر کر دیا ہے۔ اس میں مہاجرین کو مال فے سے حصہ دینے کے ساتھ ساتھ ان کے اخلاص اور سچائی کی تصدیق کی گئی ہے، نیز یہ بھی بتایا گیا ہے کہ یہ لوگ اللہ اور اس کے رسول کے مددگار ہیں۔ ایک دوسری آیت میں اللہ تعالیٰ نے مہاجرین کی صفت صبر کا تذکرہ کیا ہے اور دنیا میں عزت کے ساتھ ساتھ آخرت میں بھی اجر عظیم کی نوید سنائی ہے، پھر یہ بھی بتایا گیا ہے کہ وہ اللہ پر توکل کرنے والے ہیں اور دنیاوی جاہ و منزلت سے بہت بے پروا اور قطعی بے نیاز ہیں، فرمایا:\n﴿وَالَّذِينَ هَاجَرُوا فِي اللَّهِ مِن بَعْدِ مَا ظُلِمُوا لَنُبَوِّئَنَّهُمْ فِي الدُّنْيَا حَسَنَةً ۖ وَلَأَجْرُ الْآخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا يَعْلَمُونَ ۝ الَّذِينَ صَبَرُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ ۝﴾\n’’اور جن لوگوں نے ظلم و ستم سہنے کے بعد اللہ کی راہ میں ہجرت کی، ہم انھیں دنیا میں ضرور اچھا (ٹھکانا) دیں گے اور یقیناً آخرت کا اجر تو اس سے بھی بہت بڑا ہے۔ کاش! وہ (لوگ) علم رکھتے۔ یہ وہ لوگ ہیں جنھوں","",{"v":400327,"fn":"(1) الأنفال 8:74\n(2) الحشر 59:8"}],[1918,"نے صبر کیا اور (یہی لوگ) اپنے رب پر توکل کرتے ہیں۔‘‘(1)\nمہاجرین کی ایک نمایاں صفت، جس پر اللہ تعالیٰ نے ان کی ستائش کی ہے، رحمت الہی کا امیدوار ہونا ہے۔ اللہ تعالیٰ نے ارشاد فرمایا:\n﴿إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ أُولَٰئِكَ يَرْجُونَ رَحْمَتَ اللَّهِ ۚ وَاللَّهُ غَفُورٌ رَّحِيمٌ ۝﴾\n’’بے شک جو لوگ ایمان لائے اور جنھوں نے ہجرت کی اور اللہ کی راہ میں جہاد کیا، وہی لوگ اللہ کی رحمت کی امید رکھتے ہیں اور اللہ بخشنے والا، رحم کرنے والا ہے۔‘‘(2)\nدنیا میں کوئی انسان اطاعت و فرماں برداری کی کتنی ہی منزلیں طے کرے، اسے جنتی ہونے کا یقین نہیں ہو سکتا کیونکہ یہ معاملہ علم غیب سے تعلق رکھتا ہے اور جنت عطا فرمانا صرف اللہ ہی کے فضل و کرم پر موقوف ہے۔ مہاجرین کو اللہ تعالیٰ نے اپنی بخشش سے نواز دیا تھا۔ اس کے باوجود وہ شام و سحر اللہ کی رحمت کے طلبگار رہتے تھے۔ یہ ان کے بڑے محکم ایمان کی نشانی ہے۔(3)\nنیز اللہ تعالیٰ نے فرمایا:\n﴿وَمَن يُهَاجِرْ فِي سَبِيلِ اللَّهِ يَجِدْ فِي الْأَرْضِ مُرَاغَمًا كَثِيرًا وَسَعَةً ۚ وَمَن يَخْرُجْ مِن بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ ۗ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا ۝﴾\n’’اور جو شخص اللہ کی راہ میں ہجرت کرے، وہ زمین میں پناہ لینے کے لیے بہت جگہ اور گنجائش پائے گا۔ اور جو شخص اللہ اور اس کے رسول کی طرف ہجرت کرنے کی خاطر اپنے گھر سے نکلے، پھر اسے موت آ جائے تو اس کا اجر اللہ کے ذمے ہو گیا اور اللہ بخشنے والا، نہایت رحم کرنے والا ہے۔‘‘(4)\nدنیا میں ان کا رزق یوں فراخ کیا گیا کہ اللہ تعالیٰ نے فے اور غنیمت کا مال ان کے لیے جہاد کرنے کی وجہ سے خاص کر دیا۔ رزق میں فراخی اس طرح بھی کی گئی کہ انصار کے سینے مہاجرین کے لیے کشادہ کر دیے گئے۔ ارشاد باری تعالیٰ ہے:\n﴿وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِّمَّا أُوتُوا وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ۝﴾","",{"v":400328,"fn":"(1) النحل 16:41,42\n(2) البقرة 2:218\n(3) تفسير القرطبي، تفسير أبي السعود، البقرة 2:218\n(4) النساء 4:100"}],[1919,"اور (مال فے ان کے لیے ہے) جنھوں نے (مدینہ کو) گھر بنا لیا تھا اور ان (مہاجرین کی مدینہ تشریف آوری) سے پہلے ایمان لا چکے تھے، وہ (انصار) ان سے محبت کرتے ہیں جو ان کی طرف ہجرت کرے اور وہ اپنے دلوں میں اس (مال) کی کوئی حاجت نہیں پاتے جو ان (مہاجرین) کو دیا جائے اور اپنی ذات پر (ان کو) ترجیح دیتے ہیں اگرچہ خود انھیں سخت ضرورت ہو اور جو کوئی اپنے نفس کے لالچ سے بچا لیا گیا تو وہی لوگ فلاح پانے والے ہیں۔‘‘(1)\nاللہ تعالیٰ نے مہاجرین سے دنیا میں رزق کی فراخی کا وعدہ فرمایا۔ یہ وعدہ پورا ہوا۔ تفصیل اس اجمال کی یہ ہے کہ اللہ تعالیٰ نے ہجرت کرنے والوں کو واضح طور پر تمام ممکنہ خطرات سے آگاہ کیا اور راہ ہجرت میں پیش آنے والے تمام مصائب حتیٰ کہ موت کا ذکر بھی کر دیا۔ اس کے ساتھ چند ایسے حقائق بھی سامنے رکھ دیے جن سے اطمینان قلب اور ہجرت کے سلسلے میں اللہ کی طرف سے ضمانت حاصل ہوتی ہے۔ ضمانت کا مطلب یہ ہے کہ ہجرت اللہ کے راستے میں ہو گی۔ اسلام میں یہی ہجرت معتبر ہے، نہ کہ وہ ہجرت جو حصول مال، دکھوں سے نجات، لذتوں کے حصول یا دنیاوی ساز و سامان اکٹھا کرنے کی غرض سے ہو۔ اللہ کے لیے کی گئی ہجرت ہی اللہ کے ہاں مقبول ہے اور اللہ ہی کے لیے ہجرت کرنے والا مہاجر زمین میں کشادگی، نجات اور رزق پائے گا کیونکہ اللہ تعالیٰ اس کا مددگار ہو گا اور اسی کی راہنمائی کرے گا۔(2)\nگناہوں کی مغفرت بھی مہاجرین کے لیے خصوصی انعام تھا۔ اللہ تعالیٰ نے ارشاد فرمایا:\n﴿فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّهِ ۗ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ ۝﴾\n’’پس جن لوگوں نے ہجرت کی اور انھیں ان کے گھروں سے نکال دیا گیا اور میری راہ میں تکلیفیں دی گئیں اور انھوں نے جہاد کیا اور وہ قتل ہوئے تو میں ضرور ان کی برائیاں ان سے ختم کر دوں گا اور یقیناً انھیں ایسے باغوں میں داخل کروں گا جن کے نیچے نہریں جاری ہیں۔ یہ اللہ کی طرف سے معاوضہ ہو گا اور اللہ ہی کے پاس بہترین ثواب ہے۔‘‘(3)\nرسول اللہ صلی اللہ علیہ وسلم کے متعدد فرامین اس امر کے شاہد ہیں کہ ہجرت گناہوں کی مغفرت کا اہم ذریعہ ہے۔ سیدنا عمرو","",{"v":400329,"fn":"(1) الحشر 59:9\n(2) تفسير في ظلال القرآن لسيد قطب: 745/2\n(3) آل عمران 3:195"}],[1920,"بن عاص رضی اللہ عنہ فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n«أَمَا عَلِمْتَ يَا عَمْرُو! أَنَّ الْإِسْلَامَ يَهْدِمُ مَا كَانَ قَبْلَهُ؟ وَأَنَّ الْهِجْرَةَ تَهْدِمُ مَا كَانَ قَبْلَهَا، وَأَنَّ الْحَجَّ يَهْدِمُ مَا كَانَ قَبْلَهُ؟»\n’’اے عمرو! کیا آپ کو علم نہیں کہ اسلام کی قبولیت پچھلے گناہوں کو مٹا دیتی ہے؟ ہجرت اور حج بھی سابقہ تمام گناہوں کا خاتمہ کر دیتا ہے۔‘‘(1)\nقرآن کریم میں مہاجرین کے لیے انعامات بیان کرتے ہوئے اللہ تعالیٰ نے جنت کے استحقاق اور اس میں ہمیشہ کے قیام کا ذکر بھی کیا ہے۔ اللہ تعالیٰ کا ارشاد ہے:\n﴿الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ اللَّهِ ۚ وَأُولَٰئِكَ هُمُ الْفَائِزُونَ ۝ يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَانٍ وَجَنَّاتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ ۝ خَالِدِينَ فِيهَا أَبَدًا ۚ إِنَّ اللَّهَ عِندَهُ أَجْرٌ عَظِيمٌ ۝﴾\n’’وہ لوگ جو ایمان لائے اور انھوں نے ہجرت کی اور اللہ کی راہ میں اپنے مالوں اور اپنی جانوں سے جہاد کیا، اللہ کے ہاں درجے میں (وہ) سب سے بڑھ کر ہیں اور وہی مراد پانے والے ہیں، ان کا رب انھیں اپنی طرف سے رحمت اور رضامندی اور ایسے باغوں کی خوشخبری دیتا ہے جن میں ان کے لیے ہمیشہ رہنے والی نعمتیں ہوں گی، وہ ان میں ہمیشہ رہیں گے ابد تک۔ بے شک اللہ کے ہاں بہت بڑا اجر ہے۔‘‘(2)\nامام رازی لکھتے ہیں: ’’آیت کریمہ میں جن افراد کو چار صفات سے متصف بتایا گیا ہے، وہ عظمت کے مینار ہیں۔ انسان کے پاس بنیادی طور پر تین ہی چیزیں ہیں: روح، بدن اور مال و متاع۔ مہاجرین کی روح اسلام لانے کے بعد اوج کمال تک جا پہنچی۔ بدن اور مال انھوں نے ہجرت اور جہاد پر قربان کر دیے، حالانکہ یہ دونوں چیزیں انسان کی محبوب ترین چیزیں ہیں۔ وہ انھیں اسی صورت میں چھوڑ سکتا ہے جب ان سے زیادہ محبوب شے پا لے۔ مہاجرین کے نزدیک اللہ کی رضا جان و مال سے زیادہ محبوب نہ ہوتی تو وہ آخرت کو دنیا پر کبھی ترجیح نہ دیتے، نہ جان و مال کی قربانی پیش کرتے، لہٰذا ثابت ہوا کہ ان چار صفات سے متصف انسان انسانیت کے اعلیٰ معیار تک پہنچ جاتا ہے۔ یوں مہاجرین مطلق طور پر ساری انسانیت پر فائق تھے۔ جو صفات ان میں پائی جاتی تھیں، انھوں نے انھیں سعادت و فضیلت کے اعلیٰ درجے پر پہنچا دیا۔‘‘(3)","",{"v":400330,"fn":"(1) صحيح مسلم: 121\n(2) التوبة 9:20-22\n(3) تفسير الرازي، التوبة 9:20-22"}],[1921,"مہاجرین نے ایمان راسخ اور یقین محکم کی بدولت اسلامی دعوت کو جو ابھی ابتدائی مراحل میں تھی، جاہلیت کے ہاتھوں زندہ درگور ہونے سے بچا لیا۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم پر نازل ہونے والی وحی کی تعلیمات پر مستقل مزاجی سے عمل کیا۔ قریش کی شدید مخالفت نے ان کی استقامت میں اضافہ ہی کیا۔ مشرکین کے ظلم و ستم حد سے بڑھ گئے تو اللہ تعالیٰ نے صابر مومنین کو ہجرت کی اجازت دے دی۔ انھوں نے گھر بار، مال و متاع کو خیر باد کہا اور مدینہ روانہ ہو گئے۔ یہ ہجرت کفر کے ڈر سے نہیں تھی، نہ اس میں دنیاوی اغراض کا کوئی شائبہ تھا۔ مسلمان اس ہجرت کے ذریعے سے اللہ تعالیٰ کی رحمت کے طلبگار اور اس کی رضا کے متلاشی تھے۔ یہی وجہ ہے کہ وہ اس دنیا میں فضل الہی کے مستحق ٹھہرے اور قیامت کے دن ثواب عظیم سے بہرہ مند ہوں گے۔(1)\n§مسلمانوں میں پھوٹ ڈالنے کی سازش\nایک مرتبہ ایک بوڑھا یہودی شاس بن قیس صحابہ کرام رضی اللہ عنہم کی جماعت کے پاس سے گزرا۔ یہ شخص انتہائی کینہ پرور تھا اور مسلمانوں سے شدید حسد رکھتا تھا۔ صحابہ کرام کی جماعت میں اوس و خزرج اکٹھے بیٹھے لطف و محبت کی باتیں کر رہے تھے۔ شاس بن قیس صحابہ کی الفت و محبت اور اسلامی بھائی چارے کا یہ خوبصورت منظر برداشت نہ کر سکا۔ اس نے ایک یہودی جوان کو، جس کے انصار سے تعلقات تھے، اُکسایا کہ وہ اس مجلس میں شریک ہو جائے اور کسی حوالے سے جنگ بعاث اور اس سے پہلے کی جنگوں کا ذکر چھیڑ دے اور ان موقعوں پر کہے ہوئے اشعار بھی پڑھے تا کہ دونوں قبیلوں کے پرانے زخم ہرے ہو جائیں اور جاہلی حمیت اپنا رنگ دکھائے۔\nیہ سازش بے نتیجہ نہیں رہی۔ ان دونوں قبیلوں کی رگِ رقابت پھڑک اٹھی۔ قریب تھا کہ تلواریں میانوں سے نکل آتیں، اتنے میں رسول اللہ صلی اللہ علیہ وسلم مہاجرین کے ساتھ تشریف لے آئے۔ آپ صلی اللہ علیہ وسلم نے اپنے ارشادات کی برکت سے ان کے ایمان کا شعلہ فروزاں اور ان کا دینی جذبہ بیدار کر دیا۔ آپ صلی اللہ علیہ وسلم نے انھیں اللہ تعالیٰ سے ڈرایا اور فرمایا: ’’میرے ہوتے ہوئے بھی تم جاہلیت کی پکار لگا رہے ہو، حالانکہ اللہ نے تمھیں اسلام کی ہدایت عطا کر دی ہے اور اسلام کی بدولت تمھیں معزز بنا دیا ہے۔ تمھیں جاہلیت سے چھٹکارا دلایا، تمھیں کفر کی ضلالت سے نکالا اور بھائی بھائی بنا دیا۔‘‘ یہ ارشاد عالی سن کر انھیں احساس ہوا کہ وہ دشمن کی سازش کا شکار ہو گئے تھے۔ پھر ان کی آنکھوں سے اشک رواں کی جھڑی لگ گئی۔ اوس و خزرج یوں بغل گیر ہو گئے جیسے کوئی ناگوار بات ظہور ہی میں نہیں آئی تھی۔(2)","",{"v":400331,"fn":"(1) هجرة الرسول وصحابته في القرآن والسنة لأحمد عبد الغني، ص: 332,333\n(2) تفسير الطبري، تفسير البغوي، آل عمران 3:98,99"}],[1922,"شاس بن قیس کی اس گھناونی سازش کے بارے میں یہ آیات نازل ہوئیں:\n﴿قُلْ يَا أَهْلَ الْكِتَابِ لِمَ تَكْفُرُونَ بِآيَاتِ اللَّهِ وَاللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ ۝ قُلْ يَا أَهْلَ الْكِتَابِ لِمَ تَصُدُّونَ عَن سَبِيلِ اللَّهِ مَنْ آمَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَاءُ ۗ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ ۝﴾ (آل عمران 3:98,99)\n’’(اے نبی!) کہہ دیجیے! اے اہل کتاب! تم اللہ کی آیتوں کا انکار کیوں کرتے ہو؟ اللہ اس پر گواہ ہے جو کچھ تم کرتے ہو۔ کہہ دیجیے: اے اہل کتاب! تم اس شخص کو اللہ کے راستے سے کیوں روکتے ہو جو ایمان لے آیا؟ تم چاہتے ہو کہ وہ ٹیڑھے راستے پر چلے، حالانکہ تم خود (اس کے) گواہ ہو اور تم جو کچھ کرتے ہو اللہ اس سے غافل نہیں۔‘‘(1)\n§رسول اللہ صلی اللہ علیہ وسلم کو درپیش نت نئے مسائل\nمکہ میں دعوت اسلام کو روکنے والے صرف قریش تھے جبکہ مدینہ میں مشرکین، یہود اور نصاریٰ سب مخالف تھے۔ یہاں مشرکین اور یہودیوں کی اکثریت تھی۔ عیسائی قلیل تعداد میں تھے۔ مدینہ کے آس پاس کے قبائل بھی اسلامی دعوت کے سخت مخالف تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سب سے بیک وقت معاملہ فہمی کا ایسا برتاؤ فرمایا کہ تاریخ عالم میں اس کی مثال نہیں ملتی۔\nسب سے پہلے آپ صلی اللہ علیہ وسلم نے مہاجرین و انصار کے درمیان مواخات (اسلامی بھائی چارہ) کا رشتہ قائم کیا، پھر یہود اور مسلمانوں کے درمیان معاہدہ تحریر کیا جو تاریخ میں پہلا دستاویزی معاہدہ کہلاتا ہے۔ اسی طرح مدینہ کے آس پاس کے قبائل سے بھی آپ صلی اللہ علیہ وسلم نے معاہدے کیے۔ ان سب معاہدوں کی تفصیل آئندہ صفحات میں آئے گی۔","",{"v":400332,"fn":"(1) السيرة لابن هشام: 555,556/2، نبی رحمت صلی اللہ علیہ وسلم، ص: 235-237"}],[1923,"§ہجرت کے بعد مرض و شفا، اولین پیدائش اور وفات\n§ابوبکر، عامر بن فہیرہ اور بلال رضی اللہ عنہم کی بیماری اور دعائے نبوی\nجب مہاجرین نے مدینہ میں سکونت اختیار کر لی تو ان پر مدینہ کا وبائی بخار مسلط ہو گیا۔ مدینہ کی یہ وبا جاہلیت کے زمانے میں سب کے ہاں معروف تھی۔ کوئی بھی انسان جب مدینہ میں داخل ہوتا اور یہ چاہتا کہ وہ مدینہ کی وبائی بیماری سے محفوظ رہے تو اس سے کہا جاتا تھا کہ وہ گدھے کی طرح رینگے۔(1)\nعبداللہ بن عمرو بن عاص رضی اللہ عنہما بیان کرتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم مدینہ آئے تو آپ کے صحابہ کو مدینہ کے بخار نے آ لیا اور انھیں سخت مشقت و تکلیف میں مبتلا کر دیا حتیٰ کہ وہ نماز بھی بیٹھ کر ادا کرنے لگے۔ ایک دن رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے نکلے۔ اس وقت صحابہ بیٹھ کر ہی نماز ادا کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جان لو! بیٹھ کر نماز پڑھنے والے کا اجر کھڑے ہو کر نماز پڑھنے والے کے اجر کا نصف ہے۔‘‘ مسلمان اپنے ضعف اور بیماری کے باوجود کھڑے ہو گئے تا کہ وہ فضیلت حاصل کر سکیں۔(2)\n§بیماری میں مبتلا ہونے والے حضرات\nسیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں: رسول اللہ صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو وہاں بخار کی وبا پھیلی ہوئی تھی جس کی زد میں آ کر بہت سے صحابہ بھی بیماری اور شدید اذیت میں مبتلا ہو گئے۔ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو اس بخار سے محفوظ رکھا۔ سیدہ فرماتی ہیں: ایک ہی گھر میں ابوبکر، بلال اور عامر بن فہیرہ رضی اللہ عنہم رہتے تھے۔ بلال اور عامر بن فہیرہ ابوبکر رضی اللہ عنہ کے آزاد کردہ غلام تھے۔ ان سب کو بخار نے آ لیا۔ یہ حجاب کی پابندی سے پہلے کی بات ہے۔\n§وبا میں مبتلا شخصیات کے منظوم تاثرات\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: میں اپنے والد کے قریب پہنچی اور پوچھا: ابا جان! آپ کیسے ہیں؟ اس پر انھوں نے یہ","",{"v":400333,"fn":"(1) فتح الباري: 327,328/7\n(2) السيرة لابن هشام: 590/2"}],[1924,"شعر کہا:\nكُلُّ امْرِئٍ مُّصَبَّحٌ فِي أَهْلِهِ وَالْمَوْتُ أَدْنَىٰ مِنْ شِرَاكِ نَعْلِهِ\n’’ہر شخص اپنے گھر والوں کے ساتھ صبح کرتا ہے اور موت تو اس کی چپل کے تسمے سے بھی زیادہ قریب ہے۔‘‘\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: میں نے (دل میں) کہا: پتہ نہیں والد گرامی کیا کہہ رہے ہیں۔ پھر میں عامر بن فہیرہ کے پاس گئی۔ میں نے پوچھا: اے عامر! تمھارا کیا حال ہے؟ انھوں نے جواب میں یہ اشعار کہے:\nلَقَدْ وَجَدْتُ الْمَوْتَ قَبْلَ ذَوْقِهِ إِنَّ الْجَبَانَ حَتْفُهُ مِنْ فَوْقِهِ\nكُلُّ امْرِئٍ مُّجَاهِدٌ بِطَوْقِهِ كَالثَّوْرِ يَحْمِي جِلْدَهُ بِرَوْقِهِ\n’’میں نے موت کا ذائقہ اس کے چکھنے سے پہلے ہی محسوس کر لیا ہے۔ بے شک بزدل کی موت اس کے سر پر سوار رہتی ہے۔ ہر آدمی اپنی طاقت کے مطابق کوشش کرتا ہے جیسے بیل اپنے آپ کو سینگوں کے ذریعے بچاتا ہے۔‘‘\nعائشہ رضی اللہ عنہا کہتی ہیں: میں نے کہا: اللہ کی قسم! معلوم نہیں عامر کیا کہہ رہا ہے۔ بلال رضی اللہ عنہ کا حال یہ تھا کہ جب بخار میں تھوڑی تخفیف ہوتی تو گھر کے صحن میں لیٹ جاتے اور بلند آواز میں یہ اشعار دہراتے:\nأَلَا لَيْتَ شِعْرِي هَلْ أَبِيتَنَّ لَيْلَةً بِوَادٍ وَحَوْلِي إِذْخِرٌ وَجَلِيلُ\nوَهَلْ أَرِدَنْ يَوْمًا مِّيَاهَ مَجَنَّةٍ وَهَلْ يَبْدُوَنَّ لِي شَامَةٌ وَطَفِيلُ\n’’کاش! مجھے یہ معلوم ہو جاتا کہ میں ایک رات بھی وادی مکہ میں گزار سکوں گا جبکہ میرے ارد گرد (خوشبودار گھاس) اذخر اور جلیل ہوں گی، اور کیا ایک دن بھی مجھے ایسا ملے گا جب میں مقام مجنہ کے پانی پر جاؤں گا اور کیا میں شامہ اور طفیل کی پہاڑیاں ایک نظر دیکھ سکوں گا۔‘‘\n§بیماری کی جحفہ منتقلی\nعائشہ رضی اللہ عنہا کہتی ہیں: میں نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا اور کہا: بخار کی شدت اتنی ہے کہ یہ لوگ حواس باختہ ہو گئے ہیں اور اپنی ہی کہی ہوئی باتوں کو سمجھ نہیں پا رہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n«اللَّهُمَّ حَبِّبْ إِلَيْنَا الْمَدِينَةَ كَحُبِّنَا مَكَّةَ أَوْ أَشَدَّ، وَصَحِّحْهَا وَبَارِكْ لَنَا فِي صَاعِهَا وَمُدِّهَا، وَانْقُلْ حُمَّاهَا فَاجْعَلْهَا بِالْجُحْفَةِ»","",{"v":400334}],[1925,"اے اللہ! مدینہ کو ہمارے لیے ویسا ہی محبوب بنا دے جیسا محبوب مکہ تھا یا اس سے بھی زیادہ اور اسے\n[تصویر: اذخر گھاس]\nدرست فرما دے اور اس کے مد اور صاع میں برکت فرما اور اس کی وبا کو جحفہ کی طرف منتقل فرما۔‘‘(1)\nصحابہ میں سے جن کی بیماری کا ذکر ملتا ہے، ان میں سیدہ عائشہ رضی اللہ عنہا بھی ہیں۔(2)\nرسول اللہ صلی اللہ علیہ وسلم کی دعا کی وجہ سے یہ بیماری مہیعہ کی طرف منتقل ہو گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے خواب دیکھا کہ ایک بکھرے بالوں والی کالی عورت مدینہ سے نکل گئی اور مہیعہ میں جا بسی۔ میں نے اس کی تاویل یہ کی کہ مدینہ کی وبا مہیعہ منتقل کر دی گئی ہے۔‘‘(3) مہیعہ اور جحفہ ایک ہی مقام کے دو نام ہیں۔ ہشام بن عروہ کہتے ہیں: جحفہ (مہیعہ) میں پیدا ہونے والے بچے کو بیماری بلوغت سے پہلے ہی قتل کر دیتی ہے۔(4)\n§مہاجرین میں سے پہلے فوت ہونے والے فرد\nسیدنا عثمان بن مظعون رضی اللہ عنہ سابقین الاولین میں سے ہیں۔ ان کے احوال جلد سوم میں بیان ہو چکے ہیں۔ یہاں بعد از ہجرت صرف ان کی وفات کا تذکرہ ہے۔ یہ ہجرت کے 22 ماہ بعد، سن دو ہجری میں غزوہ بدر میں شرکت کے بعد فوت ہوئے۔ مہاجرین میں یہ پہلے فرد ہیں جو مدینہ میں فوت ہوئے اور بقیع میں دفن ہوئے۔(5)","",{"v":400335,"fn":"(1) صحيح البخاري: 3926\n(2) السيرة لابن هشام: 588,589/2\n(3) صحيح البخاري: 3918\n(4) صحيح البخاري: 7038,7039، دلائل النبوة للبيهقي: 568/2\n(5) الاستيعاب، ص: 511,512، أسد الغابة: 226,227/3، الإصابة: 381,382/4","im":["v4_p335.jpg"]}],[1926,"§انصار میں سے پہلے فوت ہونے والے صحابی\nانصار میں سب سے پہلے فوت ہونے والے صحابی اسعد بن زرارہ رضی اللہ عنہ ہیں۔ امام ابن عبدالبر رحمہ اللہ نے واقدی کی سند سے لکھا ہے کہ سیدنا اسعد بن زرارہ رضی اللہ عنہ ہجرت کے چھ ماہ بعد شوال میں فوت ہوئے۔ یہ بدر سے پہلے کی بات ہے۔ اس موقع پر مسجد نبوی کی تعمیر جاری تھی۔(1)\nسنن ابن ماجہ اور اسد الغابہ وغیرہ میں ہے: اسعد بن زرارہ رضی اللہ عنہ شوال یکم ہجری میں جنگ بدر سے پہلے فوت ہو گئے۔ ان کی موت دل کے مرض (Angina) یا خناق سے ہوئی تھی۔ عربی میں اسے الذبحة کہتے ہیں۔ جب یہ فوت ہوئے، اس وقت مسجد نبوی کی تعمیر جاری تھی۔(2)\nسیدنا اسعد بن زرارہ رضی اللہ عنہ کے بارے میں حافظ ابن حجر رحمہ اللہ نے واقدی کے حوالے سے یہ دوسرا قول بھی لکھا ہے: اسعد رضی اللہ عنہ ہجرت کے نو ماہ بعد فوت ہوئے۔ انھوں نے ابن اسحاق رحمہ اللہ کے واسطے سے لکھا ہے کہ یہ شوال کا مہینہ تھا۔ امام بغوی رحمہ اللہ فرماتے ہیں: مجھے یہ خبر پہنچی ہے کہ اسعد رضی اللہ عنہ ہجرت کے بعد فوت ہونے والے پہلے صحابی ہیں اور یہی وہ پہلے شخص ہیں جن کا رسول اللہ صلی اللہ علیہ وسلم نے جنازہ پڑھا۔\nواقدی نے عبداللہ بن ابی بکر بن حزم کی سند سے روایت کیا ہے۔ انھوں نے بتایا ہے کہ انصار کہتے ہیں: بقیع میں سب سے پہلے اسعد بن زرارہ رضی اللہ عنہ دفن ہوئے اور مہاجرین کہتے ہیں کہ وہاں اولین مدفون عثمان بن مظعون رضی اللہ عنہ ہیں۔(3)\nانصار صحابہ میں سے پہلے فوت ہونے والوں میں ایک نام سیدنا کلثوم بن ہدم رضی اللہ عنہ کا بھی ہے۔ علامہ ابن عبدالبر رحمہ اللہ نے کلثوم بن ہدم رضی اللہ عنہ کے حالات میں لکھا ہے: کلثوم رضی اللہ عنہ جنگ بدر سے تھوڑی مدت پہلے فوت ہوئے تھے۔ کہا جاتا ہے کہ کلثوم بن ہدم رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے مدینہ تشریف لانے کے بعد سب سے پہلے فوت ہونے والوں میں سے ہیں۔ امام طبری، ابن قتیبہ اور سہیلی رحمہم اللہ نے کہا ہے: سیدنا کلثوم بن ہدم رضی اللہ عنہ انصار میں سب سے پہلے فوت ہوئے۔ یہ رسول اللہ صلی اللہ علیہ وسلم کی مدینہ منورہ تشریف آوری کے تقریباً ایک ماہ بعد فوت ہو گئے تھے جبکہ مسجد نبوی اور رسول اللہ صلی اللہ علیہ وسلم کے گھر ابھی زیر تعمیر تھے۔ ان کی وفات ابو امامہ اسعد بن زرارہ رضی اللہ عنہ سے پہلے ہوئی تھی۔(4)\n§ہجرت سے پہلے فوت ہونے والے صحابی\nکتب احادیث و تاریخ میں ایک اور صحابی کا تذکرہ بھی ملتا ہے جو رسول اللہ صلی اللہ علیہ وسلم کے مدینہ ہجرت کرنے سے","",{"v":400336,"fn":"(1) الاستيعاب، ص: 79\n(2) سنن ابن ماجه: 3492، أسد الغابة: 84/1، واللفظ له\n(3) الإصابة: 208,209/1، المستدرك للحاكم: 186,187/3، شرح سنن أبي داود للعيني: 272/5\n(4) الاستيعاب، ص: 633، أسد الغابة: 543/3، الإصابة: 462/5، الروض الأنف: 377/1، 331/2"}],[1927,"پہلے ماہ صفر میں فوت ہوئے۔ ان کا اسم گرامی سیدنا براء بن معرور رضی اللہ عنہ ہے۔ یہ بنو سلمہ کے نقیب تھے اور عقبہ اولیٰ میں شامل تھے۔ نقیبوں میں سے انھی نے پہلے بات شروع کی تھی۔ انھوں نے سب سے پہلے قبلہ (کعبتہ اللہ) کی طرف منہ کر کے نماز پڑھی تھی۔ جب ستر انصاریوں نے بیعت کی تھی تو یہی تھے جنھوں نے سب سے پہلے اپنا ہاتھ رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ میں دیا تھا۔ یہ پہلے صحابی ہیں جنھوں نے قبر میں اپنا چہرہ بیت اللہ (کعبہ) کی طرف کرنے کی وصیت کی۔ جب رسول اللہ صلی اللہ علیہ وسلم ہجرت کر کے مدینہ تشریف لائے تو ان کی قبر پر گئے اور ان کی نماز جنازہ پڑھی۔(1)\n§ہجرت کے بعد مسلمانوں کے ہاں پہلے بچے کی پیدائش\nاس دنیا کا تسلسل نسل آدم کے تسلسل کے ساتھ ہے۔ آدم کی اولاد میں سے جو صراط مستقیم پر گامزن ہیں، وہ یقیناً خوش قسمت ہیں۔ مسلمان مکہ چھوڑ کر مدینہ آئے تو مشرکوں اور یہودیوں نے یہ پراپیگنڈا کیا کہ مسلمانوں کی نسل منقطع ہو گئی ہے۔ یہودی کہنے لگے: ہم نے ان پر جادو کر دیا ہے، لہٰذا اب ان کے ہاں کوئی بچہ پیدا نہیں ہو گا۔ مگر جب مہاجرین کے ہاں پہلا بچہ پیدا ہوا تو مسلمانوں میں خوشی کی لہر دوڑ گئی۔ یہ پہلا خوش قسمت بچہ سیدنا عبداللہ بن زبیر بن عوام قرشی رضی اللہ عنہ تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دندانِ مبارک سے کھجور چبا کر ان کے منہ میں ڈالی۔ ان کا نام عبداللہ رکھا۔ یہ بچہ سیدنا ابوبکر رضی اللہ عنہ کی صاحبزادی سیدہ اسماء رضی اللہ عنہا کا بیٹا ہے۔\nعلامہ ابن عبدالبر رحمہ اللہ نے لکھا ہے کہ ہجرت کے وقت اسماء رضی اللہ عنہا حاملہ تھیں مگر بچے کی پیدائش دو ہجری میں ہوئی، یہ بھی کہا جاتا ہے کہ ہجرت کے پہلے سال ان کی پیدائش ہوئی اور یہ ہجرت کے بعد مسلمانوں میں پیدا ہونے والا پہلا بچہ تھا۔\nابن عبدالبر رحمہ اللہ نے ہشام بن عروہ کے حوالے سے لکھا ہے: سیدہ اسماء رضی اللہ عنہا کہتی ہیں: مکہ ہی میں میرے پیٹ میں عبداللہ کا حمل تھا، پھر میں ہجرت کر کے مدینہ آ گئی، ابھی قباء ہی میں تھی کہ بچے کی ولادت ہو گئی، پھر میں بچے کو لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی۔ آپ نے اسے اپنی گود میں بٹھا لیا۔ پھر آپ صلی اللہ علیہ وسلم نے ایک کھجور منگوا کر چبائی اور نرم کر کے بچے کے منہ میں ڈال دی۔ پہلی شے جو اس بچے کے پیٹ میں گئی، وہ آپ صلی اللہ علیہ وسلم کا لعاب مبارک تھا۔ آپ صلی اللہ علیہ وسلم نے اسے کھجور کی گھٹی دی، پھر دعا کی اور مبارک باد دی۔(2)","",{"v":400337,"fn":"(1) المستدرك للحاكم: 199/3، أسد الغابة: 201,202/1، الاستيعاب، ص: 452\n(2) أسد الغابة: 597,598/2، البداية والنهاية: 228,229/3، تاريخ الطبري: 119/2"}],[1928,"§تکمیل نماز\nنماز کو دین اسلام میں اساسی حیثیت حاصل ہے اور نماز ہی تمام عبادات کی اصل ہے۔ اس لیے اس کے بارے میں خاص خاص احکام بڑے اہتمام سے نازل ہوتے رہے۔ مکہ میں نماز کا آغاز ہوا تو اُس وقت صرف دو نمازیں تھیں۔ ایک صبح کے وقت، دوسری دن کے آخری پہر۔ ان نمازوں کی رکعات کی تعداد دو دو تھی۔ ایک قول کے مطابق صرف رات کی نماز تھی جس کی رکعات کی تعداد معین نہ تھی۔\nکچھ عرصہ اسی پر عمل رہا، پھر اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو شرف معراج سے نوازا تو اس موقع پر آپ صلی اللہ علیہ وسلم اور آپ کی امت کو جو خاص تحفہ عنایت فرمایا، وہ دن اور رات کی پانچ نمازیں ہیں۔ جب رسول کریم صلی اللہ علیہ وسلم مکہ سے ہجرت فرما کر مدینہ تشریف لائے تو نمازوں کی رکعات میں اضافہ کر دیا گیا۔ اس کے بارے میں سیدہ عائشہ رضی اللہ عنہا کی روایت ہے، فرماتی ہیں:\n﴿فَرَضَ اللَّهُ الصَّلَاةَ حِينَ فَرَضَهَا رَكْعَتَيْنِ رَكْعَتَيْنِ فِي الْحَضَرِ وَالسَّفَرِ، فَأُقِرَّتْ صَلَاةُ السَّفَرِ، وَزِيدَ فِي صَلَاةِ الْحَضَرِ﴾\n’’اللہ تعالیٰ نے جب نماز فرض کی تو حضر و سفر کی نماز دو دو رکعتیں فرض کیں، پھر سفر کی نماز تو وہی رہی، البتہ حضر (مقیم) کی نماز میں اضافہ کر دیا گیا۔‘‘(1)\nصحیح بخاری کی ایک روایت میں ذکر ہے کہ نماز میں اضافہ ہجرت کے بعد ہوا۔ سیدہ عائشہ رضی اللہ عنہا بیان فرماتی ہیں:\n﴿فُرِضَتِ الصَّلَاةُ رَكْعَتَيْنِ، ثُمَّ هَاجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفُرِضَتْ أَرْبَعًا، وَتُرِكَتْ صَلَاةُ السَّفَرِ عَلَى الْأُولَى﴾\n’’نماز کی دو رکعتیں فرض ہوئی تھیں، پھر نبی کریم صلی اللہ علیہ وسلم نے مدینہ ہجرت کی تو نماز کی چار رکعتیں فرض ہو گئیں جبکہ سفر کی نماز اپنی پہلی حالت ہی پر چھوڑ دی گئی۔‘‘(2)\nبعض روایات میں یہ الفاظ آئے ہیں:","",{"v":400338,"fn":"(1) صحیح البخاری: 350، صحیح مسلم: 685\n(2) صحیح البخاری: 3935"}],[1929,"﴿وَتُرِكَتْ صَلَاةُ السَّفَرِ عَلَى الْفَرِيضَةِ الْأُولَى﴾\n’’اور سفر کی نماز اولین فرضیت والی حالت پر چھوڑ دی گئی۔‘‘(1)\nبعض دیگر روایات میں سیدہ عائشہ رضی اللہ عنہا کا یہ ارشاد نقل ہوا ہے:\n﴿إِنَّ أَوَّلَ مَا فُرِضَتِ الصَّلَاةُ رَكْعَتَيْنِ، فَلَمَّا قَدِمَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وَاطْمَأَنَّ زَادَ رَكْعَتَيْنِ غَيْرَ الْمَغْرِبِ لِأَنَّهَا وِتْرٌ، وَصَلَاةِ الْغَدَاةِ لِطُولِ قِرَاءَتِهَا﴾\n’’پہلے پہل دو رکعت نماز فرض ہوئی، پھر جب نبی کریم صلی اللہ علیہ وسلم مدینہ تشریف لائے اور یہاں اطمینان حاصل ہو گیا تو آپ نے دو رکعتوں کا اضافہ کر دیا سوائے مغرب کی نماز کے کیونکہ وہ وتر (طاق) ہے اور فجر کی نماز کے، کیونکہ اس میں قراءت زیادہ لمبی کی جاتی ہے۔‘‘(2)\nصحیح ابن حبان اور صحیح ابن خزیمہ وغیرہ کے الفاظ ہیں: ﴿وِتْرَ النَّهَارِ﴾ یعنی ’’دن کے وتر‘‘۔ سیدہ عائشہ رضی اللہ عنہا کی یہ روایت دلالت کرتی ہے کہ پہلے پہل نماز دو دو رکعتیں تھی سوائے مغرب کے کیونکہ وہ دن کے وتر ہیں۔ بعد میں اس میں دو دو رکعت کا اضافہ کیا گیا تو نماز چار چار رکعات والی ہو گئی سوائے نماز فجر کے کہ اس میں قراءت لمبی ہوتی ہے۔\nسیدنا عبداللہ بن عباس رضی اللہ عنہما سے ایک روایت کے الفاظ ہیں:\n﴿إِنَّ اللَّهَ فَرَضَ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمُسَافِرِ رَكْعَتَيْنِ وَعَلَى الْمُقِيمِ أَرْبَعًا وَفِي الْخَوْفِ رَكْعَةً﴾\n’’بے شک اللہ تعالیٰ نے تمھارے نبی (صلی اللہ علیہ وسلم) کی زبانی مسافر کے لیے دو رکعتیں، مقیم کے لیے چار رکعتیں اور خوف کی حالت میں ایک رکعت نماز فرض کی ہے۔‘‘(3)\nیہ حدیث بظاہر سیدہ عائشہ رضی اللہ عنہا کی روایت کے مخالف معلوم ہوتی ہے مگر اس میں مخالفت والی کوئی بات نہیں کیونکہ عبداللہ بن عباس رضی اللہ عنہما ایک ایسے معاملے کی خبر دے رہے ہیں جس پر بعد میں عمل ہوتا رہا۔(4)\nشیخ البانی رحمہ اللہ نے السلسلة الصحيحة میں سیدہ عائشہ رضی اللہ عنہا کی روایت کے مخالف اقوال و آراء کا مفصل جواب دیا ہے۔(5)","",{"v":400339,"fn":"(1) صحیح مسلم: 685، سنن النسائی: 455، السنن الکبریٰ للبیہقی: 363/1\n(2) السنن الکبریٰ للبیہقی: 363/1، صحیح ابن حبان: 447/6، صحیح ابن خزیمہ: 157/1\n(3) صحیح مسلم: 687، مسند احمد: 237/1\n(4) الثمر المستطاب، ص: 51\n(5) دیکھئے: السلسلة الصحيحة: 6(2)/744-764، حدیث: 2814"}],[1930,"نماز کی تکمیل کب ہوئی؟\nسابقہ روایات سے معلوم ہوا کہ مکہ میں دو دو رکعت نماز فرض ہو گئی تھی، البتہ اس کی تکمیل (چار رکعت) کب ہوئی؟ اس کے بارے میں علامہ عینی رحمہ اللہ نے صحیح بخاری کی شرح ’’عمدة القاری‘‘ میں لکھا ہے: امام دولابی رحمہ اللہ نے کہا ہے: مقیم کی نماز کی تکمیل کا حکم بروز منگل بارہ ربیع الآخر 1ھ کو نماز ظہر کے وقت اترا، یعنی رسول اللہ صلی اللہ علیہ وسلم کے مدینہ تشریف لانے کے ایک ماہ بعد۔ عیون الاثر میں علامہ ابن سید الناس رحمہ اللہ نے بھی ایک ماہ کا وقت لکھا ہے۔(1)\nایک قول یہ بھی ہے کہ جب صحابہ کرام رضی اللہ عنہم مدینہ تشریف لائے تو وہ فرض نمازوں کے بعد نفل پڑھتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم انھیں ہدایت فرماتے تھے کہ اپنے رب کی تخفیف قبول کرو (اور زائد نماز ادا نہ کرو) مگر صحابہ پڑھتے رہے حتی کہ ہجرت کے ایک ماہ بعد بارہ ربیع الآخر کو رسول اللہ صلی اللہ علیہ وسلم نے انھیں ظہر کی نماز چار رکعت پڑھائی، پھر یہی تعداد فرض ٹھہری۔(2)\nامام سہیلی رحمہ اللہ نے سیدہ عائشہ رضی اللہ عنہا کی سابقہ روایت بیان کر کے اس کے متعلق ائمہ کے اقوال بیان کیے ہیں۔ اس کے بعد حدیث عائشہ کی وضاحت کرتے ہوئے لکھا ہے: ﴿فُرِضَتِ الصَّلَاةُ﴾ کے معنی ہوں گے: معراج کی رات جب پانچ نمازیں فرض ہوئیں، اس وقت دو دو رکعت نماز فرض ہوئی۔ حضر (مقیم) کی نماز میں اضافہ اس کے بعد کیا گیا۔ یہ بات سیدہ عائشہ رضی اللہ عنہا سے روایت کرنے والوں میں سے بعض سے مروی ہے۔ امام حسن بصری اور امام شعبی رحمہما اللہ بھی یہی فرماتے ہیں کہ حضر کی نماز میں اضافہ ہجرت کے ایک سال بعد یا اس کے قریب زمانے میں ہوا۔(3)","",{"v":400340,"fn":"(1) عمدة القاری: 192/7\n(2) البدء والتاریخ: 274/1\n(3) الروض الأنف: 423,424/1"}],[1931,"سیرت انسائیکلوپیڈیا\n§باب 6\n§مسجد نبوی کی تعمیر\nتعمیر و توسیع، روضہ شریف کی زیارت اور سلام کے آداب، محراب و منبر نبوی، اور تکمیل نماز","",{"v":400341}],[1932,"﴿وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا﴾\n’’اور یہ کہ مسجدیں اللہ ہی کے لیے ہیں، لہذا اللہ کے ساتھ کسی کو بھی نہ پکارو۔‘‘ (الجن 72:18)","",{"v":400342}],[1933,"§اس باب میں\nمسجد مسلمانوں کا دینی، تعلیمی، سیاسی، فلاحی اور دفاعی مرکز ہے۔ اللہ کے رسول صلی اللہ علیہ وسلم مدینہ تشریف لائے تو آپ صلی اللہ علیہ وسلم نے سب سے پہلے مسجد کی تعمیر پر توجہ فرمائی۔ اولاً مسجد قبا تعمیر کرائی اور پھر مسجد نبوی بنوائی۔ مسجد کی تعمیر کے کام میں دوسرے صحابہ کرام رضی اللہ عنہم کے ساتھ آپ صلی اللہ علیہ وسلم بھی بہ نفس نفیس پوری طرح شریک رہے اور اپنے شانہ مبارک پر پتھر ڈھو ڈھو کر لاتے رہے۔ آپ صلی اللہ علیہ وسلم مسلمانوں کو زیور تعلیم سے آراستہ کرنے کے کس قدر آرزو مند تھے؟ اس کا ثبوت مسجد نبوی ہی میں اس اقامتی درسگاہ سے ملتا ہے جو آپ صلی اللہ علیہ وسلم نے اصحاب صفہ کے لیے بنوائی۔ یہاں آپ مفلوک الحال اور بے خانماں صحابہ کرام رضی اللہ عنہم کو قرآن کریم اور دینی مبادیات کی تعلیم دیتے تھے۔ مسجد نبوی پتھر کی دیواروں اور کھجور کے تنوں والی چھت پر مشتمل تھی۔ مسلمانوں کی بڑھتی ہوئی تعداد اور زمانے اور زندگی کی ضروریات کے پیش نظر مسجد نبوی کی توسیع ہوتی رہی۔ وقت کی رفتار کے ساتھ ساتھ مسجد نبوی توسیع، تعمیر اور تزئین کے کن کن مراحل سے گزری؟ اس بارے میں آپ کو اس باب میں اسلاف کرام کے زمانے سے لے کر عصر حاضر تک کے تمام ارتقائی حالات کی مکمل تفصیلات ملیں گی۔","",{"v":400343}],[1934,"مسجد نبوی\n§مسجد دینی زندگی کا مرکز ہے\nمسجد روئے زمین کا سب سے زیادہ اچھا، محترم اور مقدس مقام ہے۔ مسجد کی اس سے بڑی فضیلت اور کیا ہوگی کہ یہ رب ذوالجلال کے حضور سجدہ کرنے کی جگہ ہے۔ رسالت مآب صلی اللہ علیہ وسلم کا ارشاد گرامی ہے کہ مسجد متقی کا گھر ہے۔(1) جو مسلمان مسجد میں آتا ہے، وہ اللہ رب العزت کا مہمان ہوتا ہے۔ میزبان پر مہمان کی میزبانی لازم ہو جاتی ہے۔(2) رسول اللہ صلی اللہ علیہ وسلم نے جن خوش قسمت افراد کی نسبت فرمایا ہے کہ انھیں قیامت کے دن عرش کے سائے میں جگہ دی جائے گی، ان میں ایک وہ شخص بھی ہوگا جس کا دل مسجد میں اٹکا رہتا ہے۔(3) اللہ تعالیٰ کہتے ہیں۔(4) جس مسلمان کی حرارت ایمانی جس قدر تیز ہوگی، وہ اسی نسبت سے مسجد کا دلدادہ ہوگا اور مسلمانوں کی\n[تصویر: مسجد نبوی]","",{"v":400344,"fn":"(1) المعجم الکبیر للطبرانی: 254,255/6، حدیث: 6143، السلسلة الصحيحة: 716\n(2) المعجم الکبیر للطبرانی: 253,254/6، حدیث: 6139، السلسلة الصحيحة: 1169\n(3) صحیح البخاری: 1423، صحیح مسلم: 1031\n(4) سنن ابن ماجہ: 800","im":["v4_p344.jpg"]}],[1935,"جماعت سے اس کا ربط و ضبط اتنا ہی گہرا ہوگا۔ ایک مسلمان جب مسجد میں پانچ مرتبہ حاضری دیتا ہے تو یہ اللہ تعالیٰ سے اس کے تعلق کی بڑی معتبر نشانی ہوتی ہے۔ مسجد میں حاضری کا التزام رسول اللہ صلی اللہ علیہ وسلم کی سیرت مقدسہ کی پیروی کی علامت ہے۔\nمکہ میں رسول اللہ صلی اللہ علیہ وسلم مسجد الحرام میں نماز ادا کرتے تھے اور یہی لوگوں کے جمع ہونے کی جگہ تھی۔ اس کے چاروں طرف بت تھے۔ ہر طرف شرکیہ امور جاری تھے۔ امور حج میں بھی شرک داخل ہو چکا تھا۔ لوگ ننگے طواف\n[تصویر: طواف کعبہ کا منظر]\nکرتے تھے۔ طواف میں سیٹیاں اور تالیاں بجائی جاتی تھیں۔ دوسرے لفظوں میں مسجد کا معنی و مفہوم اور تقدس ہی ختم ہو چکا تھا۔ بس نام کی حد تک حضرت ابراہیم و اسماعیل علیہما السلام کی یاد باقی تھی۔\nمدینہ منورہ میں رسول اللہ صلی اللہ علیہ وسلم کی تشریف آوری ہوئی تو لوگوں کے ایک جگہ مل کر عبادت کرنے اور دوسرے ضروری معاملات انجام دینے کی ضرورت محسوس ہوئی۔ رسول اللہ صلی اللہ علیہ وسلم نے مسجد کے لیے وہ جگہ پسند فرمائی جہاں آپ صلی اللہ علیہ وسلم کی اونٹنی بیٹھ گئی تھی۔ یہ جگہ سیدنا ابو ایوب انصاری رضی اللہ عنہ کے گھر کے سامنے تھی۔\n§مسجد صرف جائے نماز ہی نہ تھی بلکہ یہ ایک یونیورسٹی\n[تصویر: مسجد و مدرسہ ابو ایوب انصاری رضی اللہ عنہ]","",{"v":400345,"im":["v4_p345.jpg"]}],[1936,"تھی جہاں مسلمان دین و دنیا کی تعلیم پاتے تھے، اعلیٰ اخلاقیات اور اقتصادیات کے علوم حاصل کرتے تھے۔ یہیں سے بگڑے ہوئے لوگوں کو راہ ہدایت پر لانے کے لیے لشکر روانہ کیے جاتے تھے۔ یہیں پر آپس کے جھگڑے چکائے جاتے تھے اور یہی وہ مقام تھا کہ جب بھی مسلمانوں کو کوئی اہم معاملہ پیش آتا تو وہ اسی مقام مقدس کی طرف کھنچے چلے آتے تھے۔\nمسجد دل و دماغ کو پاکیزہ بنانے کی جگہ ہے۔ مسجد میں مسلمان کو اللہ کا قرب حاصل ہوتا ہے۔ مسجد مسلمان کے لیے وہی حیثیت رکھتی ہے جو حیثیت پانی مچھلی کے لیے رکھتی ہے۔ یہ ظاہری و باطنی طہارت کا مقام ہے۔ یہاں جسمانی اور روحانی نظافت حاصل ہوتی ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے:\n﴿أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا، مَا تَقُولُ ذَلِكَ يُبْقِي مِنْ دَرَنِهِ؟ قَالُوا: لَا يُبْقِي مِنْ دَرَنِهِ شَيْئًا، قَالَ: فَذَلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ يَمْحُو اللَّهُ بِهِ الْخَطَايَا﴾\n’’اگر تم میں سے کسی کے دروازے پر کوئی نہر ہو جس میں وہ روزانہ پانچ مرتبہ غسل کرتا ہو، کیا تم کہہ سکتے ہو کہ اُس پر پھر بھی کوئی میل کچیل باقی رہے گا؟‘‘ صحابہ کرام رضی اللہ عنہم نے عرض کی: ایسا کرنے سے تو ذرا سا بھی میل کچیل باقی نہیں رہے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بس پانچوں نمازوں کی مثال ایسی ہی ہے، اللہ تعالیٰ ان کی وجہ سے گناہوں کو مٹا دیتا ہے۔‘‘(1)\n§مسجد کی تعمیر\nرسول اللہ صلی اللہ علیہ وسلم کی مدینہ تشریف آوری سے پہلے سیدنا مصعب بن عمیر رضی اللہ عنہ مہاجرین و انصار کو موجودہ مسجد نبوی کی جگہ پر نماز پڑھایا کرتے اور جمعہ کا خطبہ دیا کرتے تھے۔ دراصل یہ جگہ صرف چار دیواری تھی۔ اس پر چھت نہیں تھی۔ اس کا قبلہ بیت المقدس کی طرف تھا۔ اسے سیدنا اسعد بن زرارہ رضی اللہ عنہ نے بنایا تھا۔ وہ اپنے ساتھیوں کے ساتھ اسی جگہ نماز ادا کرتے تھے اور جمعہ پڑھاتے تھے۔ جب سیدنا مصعب رضی اللہ عنہ اسلامی تعلیمات کے معلم و مبلغ کی حیثیت سے مدینہ آئے تو وہ نماز اور جمعہ پڑھانے لگے، مصعب بن عمیر رضی اللہ عنہ واپس مکہ آ گئے تا کہ نبی صلی اللہ علیہ وسلم کے ساتھ ہجرت کریں تو ان کی جگہ سیدنا اسعد بن زرارہ رضی اللہ عنہ نماز پڑھاتے اور خطبہ دیتے رہے اور جب رسول اللہ صلی اللہ علیہ وسلم ہجرت کر کے مدینہ تشریف لے آئے تو آپ صلی اللہ علیہ وسلم بھی اسی جگہ نماز ادا کرتے رہے۔ بعد ازاں آپ صلی اللہ علیہ وسلم نے اس مقام کو مسجد بنا دیا۔(2)","",{"v":400346,"fn":"(1) صحیح البخاری: 528، صحیح مسلم: 667، نیز دیکھئے: من معین السیرة، ص: 175-177\n(2) الطبقات لابن سعد: 239/1 و 609/3"}],[1937,"§مسجد نبوی کے لیے زمین کی خریداری\nامام بخاری رحمہ اللہ نے امام زہری رحمہ اللہ سے معلق بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی چلتی رہی حتی کہ مدینہ میں رسول اللہ صلی اللہ علیہ وسلم کی مسجد کی جگہ جا کر بیٹھ گئی۔ اس جگہ ان دنوں چند مسلمان اکٹھے ہو کر نماز پڑھا کرتے تھے اور یہ جگہ سیدنا اسعد بن زرارہ رضی اللہ عنہ کے زیر پرورش دو یتیم بچوں سہیل اور سہل رضی اللہ عنہما کی تھی۔ جب اس جگہ رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی بیٹھ گئی تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿هَذَا إِنْ شَاءَ اللَّهُ الْمَنْزِلُ﴾\n’’ان شاء اللہ یہی ہماری منزل (ٹھہرنے کی جگہ) ہوگی۔‘‘\nپھر رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں لڑکوں کو بلایا اور ان سے کھلیان کی قیمت دریافت کی تاکہ یہاں مسجد بنائی جائے۔ ان دونوں نے کہا: ’’اللہ کے رسول! ہم یہ زمین آپ کو ہبہ کرتے ہیں۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے یہ زمین بطور ہبہ قبول نہیں فرمائی بلکہ اسے آپ نے خرید لیا۔ مسجد کی تعمیر شروع ہوئی تو رسول اللہ صلی اللہ علیہ وسلم بھی صحابہ کے ساتھ شامل ہو گئے اور بہ نفس نفیس اینٹیں اور پتھر اٹھا اٹھا کر لاتے رہے۔(1)\nابن عیینہ رحمہ اللہ کی روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بچوں کے چچا سے بات کی کہ وہ ان سے یہ زمین خرید کر دے دیں۔ انھوں نے دونوں بچوں سے بات کی تو انھوں نے پوچھا: ’’آپ اس زمین کا کیا کریں گے؟‘‘ انھوں نے بچوں کو اصل حقیقت بتا دی کہ اس جگہ مسجد تعمیر ہوگی۔\nچنانچہ اس جگہ کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ یہاں مسجد تعمیر کی جائے۔ مسجد اور گھروں کی تعمیر مکمل ہونے تک آپ صلی اللہ علیہ وسلم سیدنا ابو ایوب رضی اللہ عنہ ہی کے ہاں مقیم رہے۔\nابن سعد کی روایت کے مطابق رسول اللہ صلی اللہ علیہ وسلم سیدنا ابو ایوب رضی اللہ عنہ کے گھر سات مہینے تک مقیم رہے۔(2)\nصحیح بخاری میں سیدنا انس رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم کی مدینہ تشریف آوری کی ابتدائی باتیں بتاتے ہیں، وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم یہ بات پسند فرماتے تھے کہ جہاں بھی نماز کا وقت ہو وہیں پڑھ لی جائے، اسی بنا پر آپ صلی اللہ علیہ وسلم بکریوں کے باڑے میں بھی نماز پڑھ لیتے تھے۔ جب آپ صلی اللہ علیہ وسلم نے مسجد بنانے کا حکم دیا تو بنو نجار کے سرکردہ افراد کو بلا بھیجا۔ وہ حاضر ہو گئے تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا:\n﴿يَا بَنِي النَّجَّارِ! ثَامِنُونِي بِحَائِطِكُمْ هَذَا﴾","",{"v":400347,"fn":"(1) صحیح البخاری: 424 و 3906\n(2) الطبقات لابن سعد: 237/1"}],[1938,"[تصویر: مسجد نبوی کا محل وقوع]\nنقشے کے اہم مقامات: مسجد نبوی، جبل احد، وادی قتاة، الغابہ، حرہ واقم، بستی بنو حارثہ، بستی بنو عبد الاشہل، بستی بنو معاویہ، بستی بنو ظفر، بستی بنو قریظہ، بستی بنو قینقاع، بستی بنو نضیر، باب شامی، باب عوالی، بئر رومہ، بئر السقیا، بئر ابی ایوب، بئر ارس، عین الشہداء، مسجد قباء، قباء، العالیہ، وادی رانوناء، وادی مہزور، وادی العقیق، مکہ کا راستہ، قباء کا راستہ، احد کا راستہ، قلعہ کعب بن اشرف، جبل عیر، ذوالحلیفہ، قصر سعید بن عاص، دار سعد بن خیثمہ، دار کلثوم بن ہدم","",{"v":400348,"im":["v4_p348.jpg"]}],[1939,"’’اے آل نجار! تم مجھے اپنے اس کھلیان (احاطے) کی قیمت بتاؤ۔‘‘(1)\nبنو نجار کہنے لگے: ’’ہم آپ سے کوئی قیمت نہیں لیں گے، اللہ کی قسم! ہم اس کی قیمت اپنے اللہ سے مانگتے ہیں۔‘‘ مگر رسول اللہ صلی اللہ علیہ وسلم نے بغیر قیمت کے زمین قبول نہیں فرمائی۔ سیدنا ابوبکر رضی اللہ عنہ کو ارشاد فرمایا: اس کی قیمت ادا کر دو تو انھوں نے دس دینار اپنی جیب سے ادا کر دیے۔(2)\n§مسجد کی تعمیر کا آغاز\nرسول اللہ صلی اللہ علیہ وسلم نے مدینہ شہر کے وسط میں ربیع الاول 1ھ بمطابق 622ء میں مسجد نبوی کی بنیاد بہ نفس نفیس اپنے دست مبارک سے رکھی۔ مسجد کی تکمیل ماہ شوال 1ھ بمطابق اپریل 623ء کو ہوئی۔\nسیدنا انس رضی اللہ عنہ فرماتے ہیں: ‘‘مسجد کی جگہ پر مشرکوں کی قبریں تھیں، کچھ کھنڈر تھے اور چند کھجور کے درخت تھے، مزید برآں پانی کا رستا ہوا ایک چشمہ بھی تھا جو پانی کی بکثرت نکاسی کی وجہ سے خشک ہو گیا۔ نبی صلی اللہ علیہ وسلم نے مشرکین کی قبریں اکھاڑنے، کھنڈر ہموار کرنے اور کھجور کے درخت کاٹنے کا حکم دیا۔ کھجور کے تنے مسجد کے قبلے کی طرف ایک صف میں لگا دیے گئے، مسجد کے دروازے کے دائیں بائیں دو پتھر رکھ دیے گئے۔\nمسجد کے قبلے کی دیوار 70 ہاتھ (تقریباً 35 میٹر) لمبی تھی۔ اس کی چوڑائی 60 ہاتھ، یعنی تقریباً 30 میٹر تھی۔ اس کی بنیاد میں پتھر چنے گئے اور اس کے اوپر کچی اینٹیں لگائی گئیں۔ چھت کی اونچائی 5 ہاتھ تھی۔ مسجد کی تعمیر کے لیے صحابہ کرام دور دور سے پتھر ڈھو ڈھو کر لا رہے تھے۔ ان کے ساتھ ساتھ خود نبی کریم صلی اللہ علیہ وسلم بھی پتھر اٹھا کر لا رہے تھے۔ اس موقع پر آپ فرماتے جاتے تھے:\n﴿اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُ الْآخِرَةِ، فَاغْفِرْ لِلْأَنْصَارِ وَالْمُهَاجِرَةِ﴾\n’’اے اللہ! اصل بھلائی تو آخرت ہی کی بھلائی ہے، تو انصار اور مہاجرین کی مغفرت فرما۔‘‘(3)\nمسجد کا اولین قبلہ بیت المقدس (مدینہ سے شمال کی جانب) تھا۔ شروع میں مسجد کے تین دروازے بنائے گئے۔ دو دروازے شرقی اور غربی اطراف میں تھے۔ ایک دروازہ پیچھے جنوب کی جانب تھا۔ مسجد کے ان دروازوں پر کواڑ نہیں تھے۔ یہ ہر وقت کھلے رہتے تھے۔ بس یوں کہیے کہ یہ مسجد میں داخلے کے راستے تھے۔ سیدنا انس رضی اللہ عنہ کی روایت کے مطابق ان دروازوں کے اطراف میں پتھروں سے بنے ہوئے ستون کھڑے کر دیے گئے تھے۔(4)","",{"v":400349,"fn":"(1) صحیح البخاری: 428، صحیح مسلم: 524\n(2) الطبقات لابن سعد: 239/1\n(3) صحیح البخاری: 428، 3932\n(4) تاریخ المسجد النبوی الشریف، ص: 41، صحیح البخاری: 428"}],[1940,"مشرقی دروازہ باب النبی (صلی اللہ علیہ وسلم) کہلاتا تھا۔ اس دروازے کی طرف سیدنا عثمان رضی اللہ عنہ کا گھر تھا، اس لیے اس دروازے کو ’’باب آل عثمان‘‘ بھی کہا جاتا تھا۔ بعد میں یہ دروازہ ’’باب جبریل‘‘ کے نام سے مشہور ہوا۔ مغربی دروازہ ’’باب الرحمہ‘‘ کے نام سے معروف ہے۔ ایک دروازہ مسجد کی پچھلی جانب تھا۔ دیوار میں قد آدم کے برابر تھیں۔ کھجوروں کے تنوں کے ستون بنائے گئے اور کھجور کی شاخیں بچھا کر چھت ڈالی گئی۔ صحابہ کرام رضی اللہ عنہم نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کیا آپ اس پر مٹی کے گارے کا پلستر نہیں کریں گے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿عَرِيشٌ كَعَرِيشِ مُوسَى، خُشَيْبَاتٌ وَثُمَامٌ، الشَّأْنُ أَعْجَلُ مِنْ ذَلِكَ﴾\n’’بس یہ موسیٰ علیہ السلام کے چھپر جیسا ہی ایک چھپر ہے۔ اس میں چند لکڑیاں اور کچھ ٹہنیاں ہیں جبکہ موت اس سے بھی زیادہ قریب ہے۔‘‘(1)\n§مسجد نبوی کی فضیلت\nرسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا:\n﴿صَلَاةٌ فِي مَسْجِدِي هَذَا خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا الْمَسْجِدَ الْحَرَامَ﴾\n’’میری اس مسجد میں ایک نماز دوسری مسجدوں میں ایک ہزار نمازیں ادا کرنے سے بہتر ہے سوائے مسجد الحرام کے (وہاں ایک لاکھ نماز ادا کرنے کا ثواب ہے۔‘‘(2)\nایک حدیث میں رسول اللہ صلی اللہ علیہ وسلم نے مسجد نبوی کی فضیلت میں فرمایا:\n﴿لَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ: الْمَسْجِدِ الْحَرَامِ وَمَسْجِدِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَسْجِدِ الْأَقْصَى﴾\n’’تین مسجدوں کے سوا کسی اور مسجد کی طرف (حصول ثواب کی نیت سے جانے کے لیے) کجاوے نہ کسے جائیں، وہ تین مسجدیں یہ ہیں: مسجد الحرام، رسول اللہ صلی اللہ علیہ وسلم کی مسجد اور مسجد اقصیٰ۔‘‘(3)\n[تصویر: مسجد اقصیٰ]\nصحیح مسلم میں ہے کہ ابو سلمہ بن عبد الرحمن اور عبداللہ الاغر","",{"v":400350,"fn":"(1) الطبقات لابن سعد: 239,240/1\n(2) صحیح البخاری: 1190، صحیح مسلم: 1394\n(3) صحیح البخاری: 1189، صحیح مسلم: 1397","im":["v4_p350.jpg"]}],[1941,"نے جو بنو جہینہ کا غلام اور سیدنا ابو ہریرہ رضی اللہ عنہ کا شاگرد تھا، سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ فرما رہے تھے:\n﴿صَلَاةٌ فِي مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنَ الْمَسَاجِدِ، إِلَّا الْمَسْجِدَ الْحَرَامَ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آخِرُ الْأَنْبِيَاءِ وَإِنَّ مَسْجِدَهُ آخِرُ الْمَسَاجِدِ﴾\n[تصویر: مسجد الحرام]\n’’رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں ایک نماز ادا کرنا دوسری مسجدوں کے مقابلے میں ایک ہزار نماز ادا کرنے سے افضل ہے سوائے مسجد الحرام کے۔ اللہ کے رسول صلی اللہ علیہ وسلم یقیناً آخری نبی ہیں اور آپ کی مسجد آخری مسجد ہے۔‘‘(1)\n[تصویر: مسجد نبوی]\nیہی حدیث سیدنا ابو ہریرہ رضی اللہ عنہ سے ان کے شاگرد عبداللہ بن ابراہیم بن قارظ بیان کرتے ہوئے کہتے ہیں: میں حلفاً کہتا ہوں، میں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ہے، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿فَإِنِّي آخِرُ الْأَنْبِيَاءِ وَإِنَّ مَسْجِدِي آخِرُ الْمَسَاجِدِ﴾\n’’میں یقیناً آخری نبی ہوں اور بے شک میری مسجد آخری مسجد ہے۔‘‘(2)\nعلمائے کرام کا اس بات پر اتفاق ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں پڑھی جانے والی نماز کی فضیلت کا تعلق ثواب کی بہتات سے ہے۔ اس عظیم المرتبت مسجد میں نماز پڑھنے کا مطلب یہ نہیں کہ کسی کی فوت شدہ نمازیں بھی اس فضیلت میں شمار کر لی جائیں گی۔ یہ بات یاد رہنی چاہیے کہ مسجد الحرام یا مسجد نبوی میں پڑھی گئی ایک نماز عدد کے لحاظ سے صرف ایک نماز ہی شمار ہوگی اور صرف ایک ہی نماز کے لیے کفایت کرے گی۔(3)\nآج کل بہت سے نادان لوگ جو نماز سے جی چراتے اور جان چھڑاتے ہیں، وہ حج یا عمرہ کرنے کے بعد کہتے ہیں: ہم نے مسجد الحرام اور مسجد نبوی میں جو نمازیں ادا کی ہیں، وہ ہماری زندگی بھر کی یا اتنے اتنے دنوں کی نمازوں","",{"v":400351,"fn":"(1) صحیح مسلم: (507)-1394\n(2) صحیح مسلم: (507)-1394\n(3) عمدة القاری: 374/7، شرح الزرقانی علی الموطأ للإمام مالک: 5/2، فیض القدیر: 3783/7","im":["v4_p351.jpg"]}],[1942,"کے لیے کافی ہیں۔ ان کا یہ خیال صحیح نہیں بلکہ صریحاً قرآن و سنت کی تعلیمات کے خلاف ہے۔ کسی عالم نے اس طرح کا فتویٰ کبھی نہیں دیا۔\nمذکورہ حدیث سے مسجد نبوی کی فضیلت ظاہر ہوتی ہے۔ اس کا یہ مطلب نہیں کہ اب آپ صلی اللہ علیہ وسلم کی مسجد کے بعد سرے سے کوئی مسجد ہی نہیں بنے گی بلکہ اس کا مفہوم یہ ہے جیسا کہ امام قرطبی رحمہ اللہ نے فرمایا ہے: اس حدیث کے دوسرے ٹکڑے میں ’’فا‘‘ ہے۔ یہ کلام کے ربط کے لیے ہوتی ہے۔ گویا آپ صلی اللہ علیہ وسلم کی مسجد دوسری مساجد پر اس لیے فضیلت رکھتی ہے کہ یہ دوسری مساجد (جو انبیاء علیہم السلام کی طرف منسوب ہیں) سے متأخر ہے، اس لیے کہ آپ صلی اللہ علیہ وسلم آخری نبی ہیں۔(1)\nجنت کا باغیچہ (رَوْضَةٌ مِّنْ رِّيَاضِ الْجَنَّةِ)\nجنت کے باغیچے یا روضہ شریفہ سے مراد مسجد نبوی میں وہ مقام ہے جو رسول کریم صلی اللہ علیہ وسلم کے منبر سے لے کر آپ صلی اللہ علیہ وسلم کے حجرہ مبارک تک ہے۔ احادیث میں اس جگہ کی بڑی فضیلت وارد ہوئی ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے\n[تصویر: ریاض الجنة کا ایک خوبصورت منظر]","",{"v":400352,"fn":"(1) فتح الباری: 88/3، عمدة القاری: 374/7، تاریخ المسجد النبوی الشریف، ص: 10","im":["v4_p352.jpg"]}],[1943,"روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ، وَمِنْبَرِي عَلَى حَوْضِي﴾\n’’میرے گھر اور میرے منبر کے درمیان کی جگہ جنت کے باغیچوں میں سے ایک باغیچہ ہے اور میرا منبر میرے حوض پر ہوگا۔‘‘(1)\nاس حدیث کی شرح میں ابن نجار رحمہ اللہ نے لکھا ہے: بعض نے کہا ہے: آپ صلی اللہ علیہ وسلم کے منبر\n[تصویر: منبر رسول صلی اللہ علیہ وسلم]\n[تصویر: روضۂ رسول صلی اللہ علیہ وسلم]","",{"v":400353,"fn":"(1) صحیح البخاری: 1196, 1888، صحیح مسلم: 1391","im":["v4_p353.jpg"]}],[1944,"اور گھر کے درمیان کا حصہ جنت کے باغوں میں سے ایک باغیچے کے بالمقابل (زمین پر) ایک ٹکڑا ہے۔ بعض یہ کہتے ہیں: یہ فی الواقع حقیقی جنت کا باغیچہ ہے۔ آخرت میں اس جگہ کو جنت میں تبدیل کر دیا جائے گا۔ بعض کا کہنا ہے: یہ ٹکڑا رحمت کے نزول کی جگہ ہے اور یہاں ذکر کے حلقے قائم کرنے سے سعادت نصیب ہوتی ہے۔ اس لحاظ سے یہ جنت کے باغیچوں میں سے ایک باغیچے کی طرح ہے۔\nحافظ ابن حجر رحمہ اللہ اس حدیث کی شرح میں فرماتے ہیں:\nاس سے مراد ہے: جنت کے باغوں کی طرح کا ایک باغ جس میں ذکر کے حلقوں میں شامل ہونے کی طرح رحمتیں نازل ہوتی اور سعادتیں نصیب ہوتی ہیں، خصوصاً اُسی طرح جس طرح رسول اللہ صلی اللہ علیہ وسلم کے دور میں رحمتوں کا نزول اور سعادتوں کا حصول ہوتا تھا۔ اس لحاظ سے حدیث کے الفاظ میں حرف تشبیہ کے بغیر تشبیہ موجود ہے۔\nیا اس کے معنی ہیں: اس میں عبادت کرنا جنت میں داخلے کی ضمانت ہے۔ اس لحاظ سے جملے میں مجاز ہے۔\nیا یہ جملہ اپنے ظاہری معنوں پر دلالت کرتا ہے اور اس سے حقیقی باغ مراد ہے کہ یہ جگہ آخرت میں بعینہ جنت میں لے جائی جائے گی۔ یہ اس حدیث کے بارے میں علمائے کرام کے اقوال کا ماحصل ہے۔\nامام سمہودی رحمہ اللہ نے کہا ہے: یہ آخری بات میرے ہاں زیادہ قوی ہے اور ابن نجار رحمہ اللہ کا مذہب بھی یہی ہے۔ امام مالک رحمہ اللہ نے بھی اسے ظاہر پر محمول کیا ہے کہ یہ ‘‘جنت کے باغوں میں سے ایک باغ ہے اور اسے جنت ہی کی طرف منتقل کر دیا جائے گا۔ یہ ٹکڑا باقی عام زمین کی طرح نہیں کہ فنا ہو کر ختم ہو جائے گا۔ امام مالک رحمہ اللہ کی اس بات پر علماء کی ایک جماعت نے موافقت کی ہے۔(1)\nحدیث کے دوسرے حصے ’’میرا منبر میرے حوض پر ہوگا‘‘ کا مفہوم یہ ہے کہ اسی منبر کو قیامت کے دن لایا جائے گا اور حوض کوثر پر نصب کر دیا جائے گا۔ اکثر علماء کا کہنا ہے کہ حوض کوثر کا منبر یہی منبر ہوگا۔ اس کی تائید سیدنا ابوسعید خدری رضی اللہ عنہ کی حدیث سے بھی ہوتی ہے:\n﴿مِنْبَرِي عَلَى تُرْعَةٍ مِنْ تُرَعِ الْجَنَّةِ﴾\n’’میرا منبر جنت کے باغوں میں سے ایک باغ میں ہوگا۔‘‘(2)\nامام طبرانی نے ابو واقد لیثی رضی اللہ عنہ کی مرفوع حدیث بیان کی ہے:","",{"v":400354,"fn":"(1) فتح الباری: 130/4، وفاء الوفا: 429,430/2\n(2) المعجم الأوسط: 96/4۔ ترعہ کے معنی بلند جگہ پر باغ کے ہیں، مزید برآں اس کے ایک معنی حوض کے بھی ہیں۔ (النھایۃ لابن الأثیر، مادۃ ترع)"}],[1945,"﴿إِنَّ قَوَائِمَ مِنْبَرِي رَوَاتِبُ فِي الْجَنَّةِ﴾\n’’بے شک میرے منبر کے پائے جنت میں نصب ہوں گے۔‘‘(1)\nبعض نے کہا ہے: اس کے معنی یہ ہیں کہ اگر کوئی شخص نبی صلی اللہ علیہ وسلم کے منبر مبارک کا قصد کر کے جائے اور اس کے پاس عبادت کرے تو اس کا یہ عمل اسے حوض کوثر پر پہنچا کر اس مقدس حوض کا پانی پینے کا مستحق بنا دے گا۔(2)\nاس حدیث سے بعض علماء نے استدلال کیا ہے کہ مدینہ مکہ سے افضل ہے کیونکہ اس میں ’’گھر سے منبر تک‘‘ کا ٹکڑا جنت میں سے ہے۔ جنت کے متعلق ایک حدیث میں رسول اللہ صلی اللہ علیہ وسلم کا ارشاد ہے:\n﴿لَقَابُ قَوْسِ أَحَدِكُمْ فِي الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا﴾\n’’جنت میں تمھاری کمان برابر جگہ دنیا اور اس میں جو کچھ ہے، اس سے بہتر ہے۔‘‘(3)\nابن حزم رحمہ اللہ نے فرمایا ہے: یہ کہنا کہ یہ ’’جنت سے ہے‘‘ مجاز ہے۔ اگر اسے حقیقی معنی پر رکھا جائے تو پھر اس کا وصف یوں ہونا چاہیے تھا جیسا کہ حقیقی جنت کے بارے میں اللہ تعالیٰ نے فرمایا ہے:\n﴿إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ﴾\n’’بے شک تیرے لیے (یہاں یہ اہتمام) ہے کہ تو اس میں نہ بھوکا ہوگا اور نہ ننگا۔‘‘(4)\nبلکہ اس سے مراد صرف یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے گھر سے منبر تک کے اس حصے میں نماز پڑھنا جنت میں جانے کا ذریعہ ہے۔ جس طرح خوشگوار دن کو جنت کے دن سے تعبیر کرتے ہیں۔ یہ اسی نوعیت کی تشبیہ ہے جیسا کہ ایک اور حدیث میں ہے: ۵\n﴿إِنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ﴾\n’’بے شک جنت تلواروں کے سائے میں ہے۔‘‘(6)\nچنانچہ اگر یہ ثابت ہو جائے کہ حدیث کے معنی حقیقت پر محمول ہیں تو تب بھی یہ فضیلت اسی خاص ٹکڑے کی ہوگی۔ مسجد نبوی کا یہ حصہ نہ صرف مسجد میں بہت مبارک جگہ ہے بلکہ تمام روئے زمین پر بالکل یکتا اور منفرد مقام ہے۔(7)","",{"v":400355,"fn":"(1) المعجم الکبیر: 245/3\n(2) فتح الباری: 130/4\n(3) صحیح البخاری: 2793، جامع الترمذی: 1651، شعب الإیمان للبیہقی: 31/6، حدیث: 7414، واللفظ لہ\n(4) طہٰ 20:118\n(5) یہ مثال عربوں کے ہاں عام ہے۔ ہمارے ہاں کی مثالوں میں ایک عام مثال خوشگوار ہوا کے بارے میں ہے جس کی نسبت کہا جاتا ہے: یہ بہشت کی ہوا چل رہی ہے یا کسی اچھے پھل کے متعلق کہتے ہیں: یہ بہشتی میوہ ہے۔\n(6) صحیح البخاری: 3025، صحیح مسلم: 1742\n(7) فتح الباری: 130/4"}],[1946,"اس کی نظیر دنیا میں کہیں اور نہیں مل سکتی۔ اس جگہ نماز و نوافل ادا کرنے کے لیے صحابہ کرام رضی اللہ عنہم کا جمگھٹا لگا رہتا تھا۔ آج بھی مسجد نبوی کا یہ حصہ مومن کے قلب کی طمانیت اور کشش کا باعث ہے۔ مسجد نبوی کے ہر زائر کو چاہیے کہ وہ مدینہ میں قیام کے دوران میں مسجد کے اس حصے میں ضرور ذکر و عبادت کا اہتمام کرے۔\n§روضہ شریفہ کی پیمائش\nابن زبالہ رحمہ اللہ پہلے مؤرخ ہیں جنھوں نے حجرہ مطہرہ اور منبر شریف کے درمیانی فاصلے کی پیمائش کی ہے اور بتایا ہے کہ یہ فاصلہ 53 ہاتھ، یعنی تقریباً 26.5 میٹر ہے۔ بعد کی توسیعات اور ترمیمات سے مسجد نبوی کا خاصہ حصہ مقصورہ شریفہ کے اندر آ چکا ہے۔ روضہ شریفہ کی موجودہ پیمائش لمبائی کے لحاظ سے 22 میٹر اور چوڑائی کے اعتبار سے 15 میٹر ہے۔\nعلمائے کرام کا اس بات پر اجماع ہے کہ وہ تمام حصہ جو حجرہ مطہرہ کے مغربی جانب منبر تک ہے، ’’ریاض الجنۃ‘‘ ہی کا باقی ماندہ حصہ ہے۔ یہ مبارک حصہ آسانی سے نمازیوں کی دسترس میں ہوتا ہے۔ لیکن یہ نقطہ نظر مسئلے کا جزوی حل ہے، یعنی یہ شرقاً غرباً وہ حصہ ہے جو روضہ مبارک کی تعمیر کے بعد بچ سکا ہے۔ اب شمالاً جنوباً اس کا تعین کیسے کیا جائے۔ اس بارے میں حدیث مبارکہ میں اس بات کی صراحت موجود ہے:\n﴿مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ﴾\n’’جو جگہ میرے گھر اور میرے منبر کے درمیان ہے، وہ جنت کے باغوں ہی میں سے ایک باغ ہے۔‘‘\nاس حدیث کی رو سے بہت سے علماء کی رائے ہے کہ بیت عائشہ رضی اللہ عنہا کی شمالاً جنوباً تحدید کو رہنما مان لیا جائے اور اسی کے تحت رقبے کا تعین کر لیا جائے، تاہم بعض علمائے کرام اس پورے حصے کو جو منبر شریف سے مشرقی جانب تھا، جس پر رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں مسجد نبوی ہوا کرتی تھی اور جو سیدۃ النساء فاطمہ رضی اللہ عنہا کے حجرے تک چلا گیا تھا، اسے ’’ریاض الجنۃ‘‘ ہی میں شمار کرتے ہیں۔ ’’روضہ شریفہ‘‘ کا موجودہ رقبہ 330 مربع میٹر (22×15 میٹر) ہے۔ یہ بات ملحوظ خاطر رہے کہ اصل رقبہ اس سے کہیں زیادہ تھا۔ حضرت عمر بن عبد العزیز رحمہ اللہ کی تعمیر پنج گوشہ سے لے کر موجودہ مقصورہ شریف کی عمارت میں اس کا بہت سا حصہ ضم ہو گیا ہے۔(1)\n§امہات المؤمنین کے گھروں کی تعمیر\nمسجد کے اطراف میں امہات المؤمنین کے لیے کچی اینٹوں سے گھر تعمیر کیے گئے۔ ان کی چھتیں کھجور کے تنوں پر","",{"v":400356,"fn":"(1) تاریخ المسجد النبوی الشریف، ص: 116"}],[1947,"شاخوں سے ڈالی گئیں۔ جب رسول اللہ صلی اللہ علیہ وسلم مسجد اور گھروں کی تعمیر سے فارغ ہوئے تو سیدہ عائشہ رضی اللہ عنہا کو دلہن بنا کر گھر لے آئے۔ آپ صلی اللہ علیہ وسلم نے انھیں اس گھر میں رکھا جس کا دروازہ مسجد میں کھلتا تھا۔ ام المؤمنین سیدہ سودہ بنت زمعہ رضی اللہ عنہا کو دوسرا گھر دیا گیا جو ’’باب جبریل‘‘ یعنی آل عثمان کے دروازے کے قریب تھا۔\n[تصویر: مسجد نبوی کا فضائی منظر]","",{"v":400357,"im":["v4_p357.jpg"]}],[1948,"مسجد نبوی کی توسیع\n§عہد نبوی میں مسجد نبوی کی توسیع\nمسجد نبوی کی مختلف ادوار میں توسیع ہوتی رہی ہے۔ ان توسیعات کے بارے میں یہاں مختصر احوال پیش کیے جاتے ہیں۔ مسجد نبوی کی تعمیر کے بعد پہلے پہل سن چار ہجری میں اس کی توسیع کا ذکر ملتا ہے جیسا کہ حافظ ابن حجر رحمہ اللہ نے فتح الباری میں بیان کیا ہے۔ لیکن دیگر مورخین یا سیرت نگاروں نے اس کا تذکرہ نہیں کیا۔(1)\nمکحول رحمہ اللہ کا بیان ہے: جب رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کی تعداد بڑھ گئی تو انھوں نے عرض کی: اللہ کے رسول! ہمارے لیے ایک مسجد بنا دیجیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿خَشَبَاتٌ وَثُمَامَاتٌ، عَرِيشٌ كَعَرِيشِ أَخِي مُوسَىٰ صَلَوَاتُ اللَّهِ عَلَيْهِ، الْأَمْرُ أَعْجَلُ مِنْ ذٰلِكَ﴾\n’’یہ چند لکڑیاں اور گھاس پھوس ہے، اور میرے بھائی موسیٰ علیہ السلام کے چھپر کے مانند ایک چھپر ہے جبکہ موت اس سے بھی زیادہ قریب ہے۔‘‘(2)\n§سات ہجری میں مسجد کی توسیع و تعمیر\nعلامہ سمہودی رحمہ اللہ کا بیان ہے کہ فتح خیبر کے بعد مسجد نبوی میں توسیع کی گئی۔ فتح خیبر سے پہلے مسجد نبوی میں کچھ مرمت کا کام یا چند ضروری تبدیلیاں کی گئی تھیں، مثلاً: شروع میں مسجد کی چھت نہیں تھی، بعد میں ڈالی گئی۔\n[تصویر: خیبر کے کھنڈر]","",{"v":400358,"fn":"(1) فتح الباری: 308/7\n(2) وفاء الوفا: 333/1","im":["v4_p358.jpg"]}],[1949,"تحویل قبلہ کے وقت بھی تبدیلی ہوئی، اور مصلا شمال سے جنوب کی سمت بنا دیا گیا۔ اسی طرح جنوب کی طرف سے مسجد میں داخلے کا دروازہ تھا، وہ شمال کی طرف منتقل کیا گیا۔ وقت کے ساتھ جوں جوں فرزندانِ توحید کی تعداد میں اضافہ ہوتا گیا، مسجد نمازیوں کے جم غفیر کے لیے ناکافی ثابت ہونے لگی۔ محرم 7ھ بمطابق جون 628ء میں غزوہ خیبر کی فتح کے بعد رسول اللہ صلی اللہ علیہ وسلم نے مسجد مبارک کی توسیع کا حکم دیا۔ شروع میں مسجد کی لمبائی اور چوڑائی سو ہاتھ سے کم تھی۔ اب اس میں اضافہ کیا گیا تو اس کی لمبائی اور چوڑائی سو ہاتھ کے قریب ہو گئی۔(1) اس موقع پر بھی نبی کریم صلی اللہ علیہ وسلم اپنے جاں نثار صحابہ رضی اللہ عنہم کے شانہ بشانہ رہ کر مسجد کی تعمیر میں عملی طور پر شریک رہے۔\nمسجد نبوی کی توسیع میں شامل کیا گیا زمین کا یہ وہی ٹکڑا تھا جسے سیدنا عثمان رضی اللہ عنہ نے اپنے ذاتی مال سے خریدا تھا اور جس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے بشارت دی تھی:\n﴿مَنْ يَشْتَرِي بُقْعَةَ آلِ فُلَانٍ فَيَزِيدُهَا فِي الْمَسْجِدِ بِخَيْرٍ لَهُ مِنْهَا فِي الْجَنَّةِ﴾\n’’آل فلاں کی زمین کون خرید کر مسجد میں شامل کرے گا تا کہ اسے جنت میں اس سے بہتر بدلہ ملے۔‘‘(2)\nمسجد نبوی کی یہ توسیع و تعمیر سات ہجری میں ہوئی، اس کے کئی دلائل ہیں: صحیح بخاری میں سیدنا ابوسعید خدری رضی اللہ عنہ اپنے بارے میں بیان کرتے ہیں: مسجد نبوی کی تعمیر کے وقت ہم ایک ایک اینٹ اٹھا کر لا رہے تھے مگر عمار رضی اللہ عنہ دو دو اینٹیں لا رہے تھے۔ نبی صلی اللہ علیہ وسلم نے انھیں دیکھا تو ان کے سر سے مٹی جھاڑی اور فرمایا:\n﴿وَيْحَ عَمَّارٍ! تَقْتُلُهُ الْفِئَةُ الْبَاغِيَةُ، يَدْعُوهُمْ إِلَى الْجَنَّةِ وَيَدْعُونَهُ إِلَى النَّارِ﴾\n’’اللہ عمار پر رحم فرمائے! اسے باغیوں کا ایک گروہ قتل کرے گا، یہ لوگوں کو جنت کی طرف بلا رہا ہوگا جبکہ لوگ اسے آگ کی طرف دعوت دے رہے ہوں گے۔‘‘\nاس موقع پر عمار رضی اللہ عنہ نے کہا: میں فتنوں سے اللہ کی پناہ مانگتا ہوں۔(3)\nیہ حدیث نبوت کے دلائل میں سے ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے عمار کے بارے میں جس طرح پیش گوئی فرمائی تھی، وہ ٹھیک اسی طرح پوری ہوئی۔ اس سے سیدنا عمار بن یاسر رضی اللہ عنہ کی فضیلت بھی ثابت ہوتی ہے۔ عہد نبوی میں مسجد نبوی کی توسیع کی یہ دلیل بھی پیش کی جاتی ہے کہ مندرجہ بالا حدیث کے راوی سیدنا ابوسعید","",{"v":400359,"fn":"(1) وفاء الوفا: 338/1، تاریخ المسجد النبوی الشریف، ص: 42\n(2) جامع الترمذی: 3703\n(3) صحیح البخاری: 447 و 2812"}],[1950,"خدری رضی اللہ عنہ کا یہ فرمانا کہ ’’ہم اینٹیں اٹھا کر لاتے تھے‘‘ اس سے استدلال کیا جاتا ہے کہ یہ بعد کی توسیع ہے، پہلی تعمیر نہیں کیونکہ جنگ احد کے موقع پر ابوسعید رضی اللہ عنہ کی عمر تیرہ سال تھی جس کی بنا پر وہ جنگ میں شریک نہ ہو سکے تھے۔ مسجد نبوی کی پہلی تعمیر کے وقت تو ان کی عمر دس سال یا اس سے بھی کم تھی، لہذا ایک بچے کا مٹی کی بڑی بڑی اینٹیں اٹھا کر لانا محال ہے، اس لیے وہ تعمیر میں کیسے شریک ہو سکتا ہے۔\nایک دلیل یہ بھی پیش کی جاتی ہے کہ زمین کا یہ ٹکڑا، جو توسیع میں شامل کیا گیا، سیدنا عثمان رضی اللہ عنہ نے اپنے ذاتی سرمائے سے خرید کر وقف کیا تھا جبکہ پہلی تعمیر کے لیے زمین کی قیمت سیدنا ابوبکر رضی اللہ عنہ نے ادا کی تھی۔\nاس امر کی ایک اور دلیل کہ مسجد نبوی کی توسیع رسول اللہ صلی اللہ علیہ وسلم کے عہد میں ہوئی تھی، یہ ہے: بنو حنیفہ کا وفد جب مدینہ آیا تو نبی صلی اللہ علیہ وسلم مسجد تعمیر کر رہے تھے۔ یہ ایک معلوم بات ہے کہ عرب کے وفود ہجرت کے فوراً بعد پہلی ہجری میں نہیں آئے تھے۔ سیرت کا مطالعہ کرنے والے بخوبی جانتے ہیں کہ وفود کی آمد کا سلسلہ اسلام کے پھیلنے اور غالب ہو جانے کے بعد شروع ہوا تھا۔(1)\n§طلق بن علی کا قصہ\nبنو حنیفہ کے وفد کی آمد کے متعلق کہ وہ مسجد نبوی کی تعمیر کے موقع پر آیا تھا، ایک حدیث موجود ہے جو صحیح ابن حبان میں قیس بن طلق اپنے والد سیدنا طلق بن علی رضی اللہ عنہ سے بیان کرتے ہیں: وہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ کی مسجد بنانے میں شریک تھا۔ اس وقت رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿قَدِّمُوا الْيَمَامِيَّ مِنَ الطِّينِ، فَإِنَّهُ مِنْ أَحْسَنِكُمْ لَهُ مَسًّا﴾\n’’یمامی (یمامہ کے رہنے والے) کو مٹی (گارے) کے قریب کر دو کیونکہ یہ تمھاری نسبت اسے اچھی طرح گوندھ سکتا ہے۔‘‘(2)\nسنن دارقطنی وغیرہ میں قیس بن طلق اپنے والد طلق رضی اللہ عنہ سے بیان کرتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس وقت صحابہ کرام مدینہ کی مسجد تعمیر کر رہے تھے اور پتھر اور اینٹیں ڈھو رہے تھے۔ میں نے کہا: اللہ کے رسول! کیا ہم بھی اسی طرح پتھر اٹھا کر لائیں جس طرح دوسرے صحابہ لا رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿لَا، وَلٰكِنِ اخْلِطْ لَهُمُ الطِّينَ يَا أَخَا الْيَمَامَةِ فَأَنْتَ أَعْلَمُ بِهِ﴾","",{"v":400360,"fn":"(1) فتح الباری لابن رجب: 485-489/2\n(2) صحیح ابن حبان (ابن بلبان): 404/3، حدیث: 1122"}],[1951,"’’نہیں، لیکن اے یمامہ کے رہنے والے بھائی! تم انھیں مٹی گوندھ کر دو کیونکہ تمھیں اس کام کا زیادہ علم ہے۔‘‘\nطلق رضی اللہ عنہ فرماتے ہیں: پھر میں انھیں گارا بنا بنا کر دیتا رہا اور وہ اینٹیں لاتے رہے۔(1)\nامام احمد رحمہ اللہ نے قیس بن طلق کے حوالے سے بیان کیا ہے، وہ اپنے باپ سے روایت کرتے ہیں، انھوں نے فرمایا: میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، اس وقت آپ صلی اللہ علیہ وسلم کے صحابہ مسجد تعمیر کر رہے تھے۔ طلق رضی اللہ عنہ فرماتے ہیں: مجھے یوں محسوس ہوا جیسے نبی صلی اللہ علیہ وسلم کو صحابہ کا کام زیادہ معیاری نہیں لگا۔ چنانچہ میں نے گسی پکڑی اور گارا بنانے لگا۔ نبی صلی اللہ علیہ وسلم کو میرا گسی پکڑنے کا سلیقہ اور گارا بنانے کا طریقہ بہت اچھا لگا۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿دَعُوا الْحَنَفِيَّ وَالطِّينَ، فَإِنَّهُ أَضْبَطُكُمْ لِلطِّينِ﴾\n’’مٹی کا کام حنفی (بنو حنیفہ کے ساتھی) کے لیے چھوڑ دو کیونکہ انھیں تمھاری نسبت اس کام میں زیادہ مہارت ہے۔‘‘(2)\nمختلف روایات میں اسی مفہوم کے دیگر الفاظ بھی آئے ہیں۔\nمسجد نبوی کی توسیع کے کام میں سیدنا ابو ہریرہ رضی اللہ عنہ کی شمولیت کا ذکر بھی ہے۔ ابو ہریرہ رضی اللہ عنہ سات ہجری میں فتح خیبر کے موقع پر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئے تھے۔ امام احمد رحمہ اللہ نے عبد اللہ بن حطب کے بیٹے کے حوالے سے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت نقل کی ہے، وہ فرماتے ہیں: صحابہ کرام رضی اللہ عنہم اور رسول اللہ صلی اللہ علیہ وسلم مسجد کی تعمیر کے لیے اینٹیں اٹھا کر لا رہے تھے۔ میں رسول اللہ صلی اللہ علیہ وسلم سے راستے ہی میں ملا۔ اس وقت آپ صلی اللہ علیہ وسلم نے اینٹ اپنے بطن مبارک سے لگا رکھی تھی۔ میں سمجھا شاید یہ بھاری ہے اور اس کی وجہ سے آپ کو مشقت اٹھانی پڑ رہی ہے۔ میں نے عرض کی: اللہ کے رسول! یہ اینٹ مجھے پکڑا دیجیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿خُذْ غَيْرَهَا يَا أَبَا هُرَيْرَةَ فَإِنَّهُ لَا عَيْشَ إِلَّا عَيْشُ الْآخِرَةِ﴾\n’’ابو ہریرہ! تم دوسری لے لو، بے شک آخرت کی زندگی ہی اصل زندگی ہے۔‘‘(3)\n§مسجد کی طرز تعمیر اور چھت\nمسجد نبوی کی پوری عمارت انتہائی سادگی اور کفایت شعاری کا مظہر تھی۔ زیب و زینت اور آرائش کا کوئی اہتمام نہیں تھا۔ اس وقت کے لحاظ سے تعمیر کا جو طریقہ اختیار کیا گیا، عرب اسے الشمیط کہتے تھے، یعنی اینٹ کے اوپر اینٹ رکھنا۔ دوسری بار تقریباً چار ہجری کے موقع پر تعمیر کا جو طریقہ مروج تھا، اسے السعیدہ کہتے تھے، یعنی پوری اینٹ اور","",{"v":400361,"fn":"(1) سنن الدارقطنی: 154/1، حدیث: 533\n(2) غایۃ المقصد فی زوائد المسند: 774/1\n(3) مسند احمد: 381/2"}],[1952,"آدھی اینٹ جوڑ کر دیوار بنانا، پھر تیسری بار فتح خیبر کے بعد مسجد کی توسیع و تعمیر ہوئی اور اس وقت جو طریقہ تعمیر اختیار کیا گیا، عرب اسے مؤنث مذکر طرز تعمیر کہتے ہیں، یعنی دو دو اینٹیں جوڑ کر دیوار بنانا۔(1)\nامام بخاری رحمہ اللہ نے سیدنا ابوسعید رضی اللہ عنہ کی ایک معلق روایت بیان کی ہے، وہ فرماتے ہیں: مسجد نبوی کی چھت کھجور کی ٹہنیاں بچھا کر ڈالی گئی تھی۔\nحضرت نافع رحمہ اللہ بیان کرتے ہیں، سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے مجھے بتایا کہ رسول اکرم صلی اللہ علیہ وسلم کے زمانے میں مسجد کچی اینٹوں سے بنائی گئی تھی۔ اس کی چھت کھجور کی ٹہنیوں سے تیار کی گئی تھی جبکہ ستون کھجور کے تنے گاڑ کر بنائے گئے تھے۔ سیدنا ابوبکر رضی اللہ عنہ نے (اپنے دور خلافت میں) اس میں کوئی اضافہ نہیں کیا۔ سیدنا عمر رضی اللہ عنہ نے مسجد کی تعمیر کی تو اس میں اضافہ کیا لیکن سامانِ تعمیر وہی استعمال کیا جو رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں استعمال ہوتا تھا۔ البتہ انھوں نے ستون لکڑی کے بنوائے تھے۔ سیدنا عثمان رضی اللہ عنہ نے اپنے دور خلافت میں مسجد نبوی کی ازسر نو تعمیر کی تو اس میں اچھا خاصا اضافہ کیا اور کئی تبدیلیاں بھی کیں، مثلاً: دیواریں منقش پتھر اور چونے کی بنائیں اور ستون بھی منقش پتھروں کے بنائے اور چھت ساگوان کی لکڑی کی ڈالی۔(2)","",{"v":400362,"fn":"(1) وفاء الوفا: 335/1\n(2) صحیح البخاری: 446، فتح الباری: 699/1"}]])